window.DQ=window.DQ||{};DQ["chavero"]={"a":[["אֶתְמוֹל שִׁמְעוֹן לֹא הִשְׁאִיל לְךָ מַחַק. הַיּוֹם הוּא מְבַקֵּשׁ מִמְּךָ סַרְגֵּל. מָה עוֹשִׂים?",["אוֹמְרִים: גַּם אַתָּה לֹא נָתַתָּ","נוֹתְנִים בְּסֵבֶר פָּנִים יָפוֹת","נוֹתְנִים וְעוֹקְצִים: אֲנִי לֹא כָּמוֹךָ"],1,"סֵרוּב כְּדֵי לְהַחְזִיר לוֹ הוּא \"לֹא תִקֹּם\", וּנְתִינָה עִם עֲקִיצָה הִיא \"לֹא תִטֹּר\". מוֹחִים אֶת הַכַּעַס מִן הַלֵּב וְנוֹתְנִים בְּחִיּוּךְ.","פֶּרֶק א׳, הֲלָכָה ו׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["בַּהַפְסָקָה חָבֵר הֶעֱלִיב אוֹתְךָ. מָה הַתּוֹרָה מְלַמֶּדֶת לַעֲשׂוֹת?",["שׁוֹתְקִים וְכוֹעֲסִים בַּלֵּב","מְחַכִּים לְהַחְזִיר לוֹ","מְדַבְּרִים אִתּוֹ בְּנַחַת"],2,"אָסוּר לִשְׂנֹא בַּלֵּב וְאָסוּר לִנְקֹם. הַתּוֹרָה מְלַמֶּדֶת לָלֶכֶת אֶל הֶחָבֵר וְלוֹמַר לוֹ בְּנַחַת: לָמָּה עָשִׂיתָ לִי כָּךְ?","פֶּרֶק א׳, הֲלָכָה ד׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אָבִי עָבַר לְיַדְךָ בָּרְחוֹב וְלֹא עָנָה לְךָ \"שָׁלוֹם\". מָה כְּדַאי לַחְשֹׁב?",["אוּלַי הוּא לֹא רָאָה אוֹתִי","הוּא כּוֹעֵס עָלַי","הוּא חוֹשֵׁב שֶׁהוּא חָשׁוּב"],0,"מַעֲשֶׂה שֶׁאֶפְשָׁר לְהָבִין לְטוֹבָה וּלְרָעָה – מִצְוָה לְהָבִין לְטוֹבָה. אוּלַי הָיָה שָׁקוּעַ בְּמַחְשָׁבוֹת וְלֹא רָאָה אוֹתְךָ.","פֶּרֶק א׳, הֲלָכוֹת ט׳–י׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["בַּהַפְסָקָה יֶלֶד מְסַפֵּר לַחֲבֵרִים דְּבָרִים רָעִים עַל יֶלֶד אַחֵר. מָה עוֹשִׂים?",["מִתְקָרְבִים לִשְׁמֹעַ","מוֹסִיפִים עוֹד סִפּוּר","לֹא שׁוֹמְעִים וְהוֹלְכִים"],2,"אָסוּר לְסַפֵּר לָשׁוֹן הָרָע, וְגַם לֹא יוֹשְׁבִים לִשְׁמֹעַ אֶת מִי שֶׁמְּסַפֵּר. מִתְרַחֲקִים בְּנִימוּס.","פֶּרֶק א׳, הֲלָכָה י״א","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אֵיזֶה מִשְּׁלוֹשֶׁת הַיְּלָדִים עוֹבֵר עַל אִסּוּר רְכִילוּת?",["לוֹחֵשׁ: פְּלוֹנִי אָמַר עָלֶיךָ","מְשַׁבֵּחַ חָבֵר לִפְנֵי הַמּוֹרֶה","מוֹסֵר לְחָבֵר דְּרִישַׁת שָׁלוֹם"],0,"רְכִילוּת הִיא לְסַפֵּר לְאָדָם מָה אָמְרוּ עָלָיו, גַּם כְּשֶׁזֶּה נָכוֹן. דִּבּוּרִים כָּאֵלֶּה מְבִיאִים לִמְרִיבוֹת בֵּין חֲבֵרִים.","פֶּרֶק א׳, הֲלָכָה י״א","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["יוֹסִי טָעָה בַּתְּשׁוּבָה מוּל כָּל הַכִּתָּה. מָה נָכוֹן לַעֲשׂוֹת?",["צוֹחֲקִים עָלָיו בְּקוֹל","לֹא צוֹחֲקִים וּמְחַיְּכִים אֵלָיו","מְחַקִּים אֶת הַטָּעוּת שֶׁלּוֹ"],1,"הַמַּלְבִּין פְּנֵי חֲבֵרוֹ בָּרַבִּים – כְּאִלּוּ שׁוֹפֵךְ דָּמִים. צְחוֹק מוּל כֻּלָּם גּוֹרֵם לוֹ בּוּשָׁה גְּדוֹלָה.","פֶּרֶק א׳, הֲלָכָה י״ד","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["בַּמִּשְׂחָק חָבֵר צָעַק עָלֶיךָ מִלָּה לֹא יָפָה. אֵיךְ עוֹצְרִים אֶת הָרִיב?",["צוֹעֲקִים עָלָיו בַּחֲזָרָה","קוֹרְאִים לַחֲבֵרִים שֶׁיַּעַזְרוּ","לֹא מַחֲזִירִים לוֹ"],2,"רִיב נִמְשָׁךְ רַק כְּשֶׁיֵּשׁ שְׁנֵי צְדָדִים. כְּשֶׁאֶחָד לֹא מַחֲזִיר – הָרִיב נֶעֱצָר כְּשֶׁהוּא עוֹד קָטָן.","פֶּרֶק א׳, הֲלָכָה ז׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["יֵשׁ בַּכִּתָּה יֶלֶד שֶׁקָּשֶׁה לְךָ לֶאֱהֹב. מָה יַעֲזֹר לְךָ לֶאֱהֹב אוֹתוֹ?",["לַעֲזֹר לוֹ בְּמַשֶּׁהוּ","לְהִתְרַחֵק מִמֶּנּוּ","לְדַבֵּר עָלָיו עִם חֲבֵרִים"],0,"הַתּוֹרָה מְלַמֶּדֶת: עֲשֵׂה חֶסֶד עִם מִי שֶׁקָּשֶׁה לְךָ לֶאֱהֹב, עֲזֹר לוֹ וְדוּן אוֹתוֹ לְכַף זְכוּת – וּתְגַלֶּה שֶׁבֶּאֱמֶת אַתָּה אוֹהֵב אוֹתוֹ.","פֶּרֶק א׳, הֲלָכָה ג׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["כַּמָּה יְלָדִים צוֹחֲקִים עַל יֶלֶד חַלָּשׁ. מָה עָלֶיךָ לַעֲשׂוֹת?",["עוֹמְדִים מִן הַצַּד וְשׁוֹתְקִים","אוֹמְרִים לָהֶם בְּנַחַת לְהַפְסִיק","מִצְטָרְפִים לַצְּחוֹק"],1,"מִצְוָה לִמְחוֹת בְּמִי שֶׁעוֹשֶׂה עֲבֵרָה, מִתּוֹךְ אַהֲבָה. מִי שֶׁיָּכוֹל לִמְנֹעַ וְשׁוֹתֵק – כְּאִלּוּ חָטָא בְּעַצְמוֹ.","פֶּרֶק א׳, הֲלָכוֹת י״ד, ט״ז","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["דָּנִי מְסַפֵּר לַחֲבֵרִים עַל הַטִּיּוּל. אֵיךְ נָכוֹן לְסַפֵּר?",["מוֹסִיף נָחָשׁ עֲנָק שֶׁלֹּא הָיָה","מְסַפֵּר בְּדִיּוּק מָה שֶׁהָיָה","אוֹמֵר שֶׁטִּפֵּס רִאשׁוֹן, וְזֶה לֹא נָכוֹן"],1,"\"מִדְּבַר שֶׁקֶר תִּרְחָק\" – גַּם שֶׁקֶר קָטָן כְּדֵי שֶׁהַסִּפּוּר יִהְיֶה מְעַנְיֵן אָסוּר. מְסַפְּרִים מָה שֶׁהָיָה בֶּאֱמֶת.","פֶּרֶק ב׳, הֲלָכוֹת ב׳–ג׳","אֱמֶת וְיֹשֶׁר"],["הַמִּבְחָן קָשֶׁה, וְאַתָּה לֹא בָּטוּחַ בַּתְּשׁוּבָה. מָה עוֹשִׂים?",["כּוֹתְבִים מָה שֶׁיּוֹדְעִים","מַעְתִּיקִים מֵהַשָּׁכֵן","מְצִיצִים בַּמַּחְבֶּרֶת"],0,"הַעְתָּקָה הִיא גְּנֵבַת דַּעַת – הַמּוֹרֶה חוֹשֵׁב שֶׁאַתָּה יוֹדֵעַ, וְזֶה לֹא נָכוֹן. הָאֱמֶת יְקָרָה יוֹתֵר מֵהַצִּיּוּן.","פֶּרֶק ב׳, הֲלָכָה י״ט","אֱמֶת וְיֹשֶׁר"],["הִבְטַחְתָּ לַעֲזֹר לְחָבֵר בְּשִׁעוּרֵי הַבַּיִת בָּעֶרֶב. פִּתְאוֹם מַזְמִינִים אוֹתְךָ לְשַׂחֵק. מָה עוֹשִׂים?",["הוֹלְכִים לְשַׂחֵק בְּלִי לְהוֹדִיעַ","אוֹמְרִים לֶחָבֵר: אֲנִי חוֹלֶה","בָּאִים לַעֲזֹר כְּמוֹ שֶׁהִבְטַחְתָּ"],2,"מִי שֶׁאָמַר שֶׁיַּעֲזֹר – צָרִיךְ לַעֲמֹד בְּדִבּוּרוֹ. מִי שֶׁלֹּא מְקַיֵּם נִקְרָא מְחֻסַּר אֲמָנָה, וְתֵרוּץ שֶׁל שֶׁקֶר מוֹסִיף עוֹד עֲבֵרָה.","פֶּרֶק ב׳, הֲלָכָה ט׳","אֱמֶת וְיֹשֶׁר"],["הַמּוֹרֶה שׁוֹאֵל אוֹתְךָ בְּשֶׁקֶט אִם חָזַרְתָּ לַמִּבְחָן, וְלֹא חָזַרְתָּ. מָה עוֹנִים?",["אוֹמְרִים אֶת הָאֱמֶת","אוֹמְרִים: כֵּן, הַרְבֵּה","מְסַפְּרִים שֶׁהַסֵּפֶר נֶעֱלַם"],0,"לַמּוֹרֶה חַיָּבִים לוֹמַר אֱמֶת, כִּי הוּא צָרִיךְ לָדַעַת אֵיפֹה הַתַּלְמִיד עוֹמֵד, כְּדֵי לַעֲזֹר לוֹ לְהִתְקַדֵּם.","פֶּרֶק ב׳, הֲלָכָה י״ז","אֱמֶת וְיֹשֶׁר"],["חָבֵר מַרְאֶה לְךָ תִּיק חָדָשׁ שֶׁקָּנָה, וְהַתִּיק לֹא מוֹצֵא חֵן בְּעֵינֶיךָ. מָה אוֹמְרִים?",["אוֹמְרִים: הוּא מְכֹעָר","צוֹחֲקִים עַל הַצֶּבַע","מְשַׁבְּחִים מַשֶּׁהוּ טוֹב בּוֹ"],2,"הוּא כְּבָר קָנָה, וּבִקֹּרֶת רַק תְּצַעֵר אוֹתוֹ. מְשַׁבְּחִים קְצָת כְּדֵי לְשַׂמֵּחַ, וְעָדִיף לְהִתְרַכֵּז בְּמַעֲלָה אֲמִתִּית שֶׁיֵּשׁ בּוֹ.","פֶּרֶק ב׳, הֲלָכָה י״ח","אֱמֶת וְיֹשֶׁר"],["חָבֵר שׁוֹאֵל אוֹתְךָ אִם יוֹסִי אָמַר עָלָיו דְּבָרִים רָעִים – וְיוֹסִי בֶּאֱמֶת אָמַר. מָה עָדִיף לַעֲשׂוֹת?",["לְסַפֵּר לוֹ כָּל מִלָּה","לְהַטּוֹת אֶת הַשִּׂיחָה לְנוֹשֵׂא אַחֵר","לְהוֹסִיף עוֹד דְּבָרִים"],1,"לְמַעַן הַשָּׁלוֹם מֻתָּר לְשַׁנּוֹת, אֲבָל לְכַתְּחִלָּה עָדִיף לְהַטּוֹת אֶת הַשִּׂיחָה. וּלְסַפֵּר לוֹ – זוֹ רְכִילוּת שֶׁמְּבִיאָה לִמְרִיבָה.","פֶּרֶק ב׳, הֲלָכָה י״ד","אֱמֶת וְיֹשֶׁר"],["בְּבֵית הַשְּׁכֵנִים מְכִינִים שִׂמְחָה. מָתַי מַצִּיעִים לָהֶם עֶזְרָה?",["כְּשֶׁהַכֹּל כְּבָר מוּכָן","אַחֲרֵי שֶׁכֻּלָּם הָלְכוּ","כְּשֶׁעוֹד יֵשׁ עֲבוֹדָה"],2,"מִי שֶׁמְּחַכֶּה שֶׁהַכֹּל יִהְיֶה מוּכָן, וְרַק אָז מַצִּיעַ עֶזְרָה – גּוֹנֵב אֶת דַּעְתָּם. עוֹזְרִים בֶּאֱמֶת, כְּשֶׁיֵּשׁ צֹרֶךְ.","פֶּרֶק ג׳, הֲלָכָה ח׳","אֱמֶת וְיֹשֶׁר"],["חָבֵר בָּא לְבַקֵּר. בַּבַּיִת יֵשׁ עוּגָה גְּדוֹלָה שֶׁאָפוּ לְשַׁבָּת. מָה נָכוֹן לוֹמַר?",["אָפִינוּ אוֹתָהּ רַק בִּשְׁבִילְךָ","בְּבַקָּשָׁה, תִּטְעַם מִמֶּנָּה","שָׁמַרְתִּי לְךָ אֶת הַחֲתִיכָה הָאַחֲרוֹנָה"],1,"אָסוּר לוֹמַר לְאוֹרֵחַ שֶׁעָשִׂינוּ מַשֶּׁהוּ לִכְבוֹדוֹ, כְּשֶׁזֶּה לֹא נָכוֹן – זוֹ גְּנֵבַת דַּעַת. מַגִּישִׁים בְּלֵב טוֹב וּבְלִי הַצָּגוֹת.","פֶּרֶק ג׳, הֲלָכָה ד׳","אֱמֶת וְיֹשֶׁר"],["שָׁבַרְתָּ בְּטָעוּת כּוֹס, וְאַבָּא שׁוֹאֵל מָה קָרָה. מָה עוֹנִים?",["אֲנִי שָׁבַרְתִּי בְּטָעוּת","אָחִי הַקָּטָן שָׁבַר","הֶחָתוּל הִפִּיל אוֹתָהּ"],0,"שֶׁקֶר שֶׁמַּפִּיל אֶת הָאַשְׁמָה עַל אַחֵר פּוֹגֵעַ בּוֹ – וְלָזֶה אֵין שׁוּם הֶתֵּר. גַּם כְּשֶׁהָאֱמֶת קָשָׁה: \"שְׂפַת אֱמֶת תִּכּוֹן לָעַד\".","פֶּרֶק ב׳, הֲלָכוֹת ג׳, ו׳","אֱמֶת וְיֹשֶׁר"],["חָבֵר הִשְׁאִיר אֶת הַקַּלְמָר שֶׁלּוֹ עַל הַשֻּׁלְחָן וְיָצָא לַהַפְסָקָה. מָה עוֹשִׂים?",["מַחְבִּיאִים אוֹתוֹ בִּצְחוֹק","מְצַיְּרִים בַּטּוּשִׁים הַחֲדָשִׁים שֶׁלּוֹ","לֹא נוֹגְעִים בְּלִי רְשׁוּת"],2,"לְהַחְבִּיא בִּצְחוֹק גּוֹרֵם לֶחָבֵר צַעַר – וְזֶה אָסוּר. וּלְהִשְׁתַּמֵּשׁ בַּטּוּשִׁים שֶׁלּוֹ בְּלִי רְשׁוּת, אֲפִלּוּ עַל מְנַת לְהַחֲזִיר, זֶה שׁוֹאֵל שֶׁלֹּא מִדַּעַת.","פֶּרֶק ד׳, הֲלָכָה א׳","לֹא תִּגְנֹבוּ"],["צְרִיכִים כַּפִּית. הַשָּׁכֵן לֹא בַּבַּיִת, וְהַדֶּלֶת שֶׁלּוֹ פְּתוּחָה. מָה עוֹשִׂים?",["מְחַכִּים וּמְבַקְּשִׁים רְשׁוּת","נִכְנָסִים וְלוֹקְחִים כַּפִּית","לוֹקְחִים וּמַחֲזִירִים מָחָר"],0,"אֲפִלּוּ כַּפִּית קְטַנָּה אָסוּר לָקַחַת מִבֵּית הַשָּׁכֵן בְּלִי רְשׁוּת – גַּם עַל מְנַת לְהַחֲזִיר.","פֶּרֶק ד׳, הֲלָכָה ג׳","לֹא תִּגְנֹבוּ"],["הֶחָבֵר יוֹשֵׁב לְיָדְךָ, וְאַתָּה צָרִיךְ אֶת הַמַּחַק שֶׁלּוֹ. מָה עוֹשִׂים?",["לוֹקְחִים בְּשֶׁקֶט","שׁוֹאֲלִים: אֶפְשָׁר בְּבַקָּשָׁה?","חוֹטְפִים וּמַחֲזִירִים מַהֵר"],1,"כְּשֶׁהַבְּעָלִים נִמְצָא – תָּמִיד מְבַקְּשִׁים רְשׁוּת. מִי שֶׁלּוֹקֵחַ בְּלִי לִשְׁאֹל, אֲפִלּוּ לְרֶגַע, הוּא שׁוֹאֵל שֶׁלֹּא מִדַּעַת.","פֶּרֶק ד׳, הֲלָכוֹת א׳, ג׳","לֹא תִּגְנֹבוּ"],["אַחֲרֵי הַטִּיּוּל גִּלִּיתָ שֶׁהַתִּיק שֶׁלְּךָ הִתְחַלֵּף בְּתִיק דּוֹמֶה. מָה עוֹשִׂים?",["פּוֹתְחִים וְלוֹקְחִים מִמֶּנּוּ אֹכֶל","מִשְׁתַּמְּשִׁים בַּתִּיק הַשֵּׁנִי","מוֹדִיעִים וּמְחַפְּשִׂים אֶת הַבְּעָלִים"],2,"אָסוּר לְהִשְׁתַּמֵּשׁ בַּתִּיק שֶׁנִּשְׁאַר – אוּלַי הוּא שֶׁל מִישֶׁהוּ שְׁלִישִׁי. מַכְרִיזִים שֶׁנִּמְצָא תִּיק וְשֶׁאָבַד תִּיק, כְּמוֹ בַּאֲבֵדָה.","פֶּרֶק ד׳, הֲלָכָה ה׳","לֹא תִּגְנֹבוּ"],["בַּחֲתֻנָּה שֶׁל הַדּוֹד נִשְׁאַר הַרְבֵּה אֹכֶל. מָה מֻתָּר לָקַחַת הַבַּיְתָה בְּלִי לִשְׁאֹל?",["מָה שֶׁנִּשְׁאַר בַּצַּלַּחַת שֶׁלִּי","עוּגוֹת מֵהַמַּגָּשׁ הַגָּדוֹל","בַּקְבּוּקִים מֵהַשֻּׁלְחָנוֹת"],0,"הָאֹכֶל שֶׁבַּצַּלַּחַת הָאִישִׁית מִמֵּילָא יִזָּרֵק, וּמֻתָּר לָקַחַת אוֹתוֹ בְּנִימוּס. מָה שֶׁבַּקְּעָרוֹת וּבַבַּקְבּוּקִים הַכְּלָלִיִּים – רַק בִּרְשׁוּת.","פֶּרֶק ד׳, הֲלָכָה ו׳","לֹא תִּגְנֹבוּ"],["בְּבֵית הַכְּנֶסֶת יֵשׁ סֵפֶר שֶׁאַתָּה רוֹצֶה לִלְמֹד בּוֹ בַּבַּיִת. מָה עוֹשִׂים?",["לוֹקְחִים, כִּי אַף אֶחָד לֹא לוֹמֵד בּוֹ","מְבַקְּשִׁים רְשׁוּת מֵהַגַּבַּאי","לוֹקְחִים, כִּי זוֹ מִצְוָה לִלְמֹד"],1,"סִפְרֵי בֵּית הַכְּנֶסֶת שַׁיָּכִים לַצִּבּוּר, וְהַגַּבָּאִים מְמֻנִּים עֲלֵיהֶם. גַּם כְּשֶׁאַף אֶחָד לֹא לוֹמֵד בָּהֶם – בְּלִי רְשׁוּתָם זוֹ גְּנֵבָה.","פֶּרֶק ד׳, הֲלָכָה ט׳","לֹא תִּגְנֹבוּ"],["בְּסֻכּוֹת, אַרְבָּעָה מִינִים שֶׁל אָדָם אַחֵר מֻנָּחִים בְּבֵית הַכְּנֶסֶת, וְהוּא לֹא כָּאן. מָה נָכוֹן?",["נוֹטְלִים שָׁם וּמַחֲזִירִים לַמָּקוֹם","לוֹקְחִים הַבַּיְתָה לְכָל הַחַג","מַנִּיחִים אַחַר כָּךְ עַל סַפְסָל רָחוֹק"],0,"נוֹחַ לְאָדָם שֶׁעוֹשִׂים מִצְוָה בְּשֶׁלּוֹ. אֲבָל רַק לְשִׁמּוּשׁ קָצָר, בְּאוֹתוֹ מָקוֹם, וּמַחֲזִירִים בְּדִיּוּק כְּמוֹ שֶׁהָיָה – כְּדֵי שֶׁהַבְּעָלִים יִמְצָא אוֹתָם מִיָּד.","פֶּרֶק ד׳, הֲלָכָה ז׳","לֹא תִּגְנֹבוּ"],["מִישֶׁהוּ עָלָה לָאוֹטוֹבּוּס וְלֹא שִׁלֵּם. מָה עוֹשִׂים קֹדֶם?",["מִתְעַלְּמִים וְיוֹשְׁבִים","צוֹעֲקִים עָלָיו מִיָּד","אוֹמְרִים לוֹ בְּנַחַת שֶׁצָּרִיךְ לְשַׁלֵּם"],2,"אֵין הֶבְדֵּל בֵּין גְּנֵבָה מֵאָדָם פְּרָטִי לִגְנֵבָה מֵחֶבְרַת אוֹטוֹבּוּסִים. קֹדֶם אוֹמְרִים בְּנַחַת, וְאִם זֶה לֹא עוֹזֵר – אוֹמְרִים לַנֶּהָג.","פֶּרֶק ד׳, הֲלָכָה י״ב","לֹא תִּגְנֹבוּ"],["בַּקִּיּוֹסְק קִבַּלְתָּ בְּטָעוּת עֹדֶף גָּדוֹל מִדַּי. מָה עוֹשִׂים?",["קוֹנִים בּוֹ עוֹד מַמְתָּק","מַחֲזִירִים לַמּוֹכֵר","שׁוֹמְרִים, כִּי הוּא טָעָה"],1,"כְּשֶׁסִּכְּמוּ עַל מְחִיר וְטָעוּ בִּסְפִירַת הַכֶּסֶף – חוֹבָה לְהַחְזִיר, אֲפִלּוּ שֶׁקֶל אֶחָד.","פֶּרֶק ד׳, הֲלָכָה י״ז","לֹא תִּגְנֹבוּ"],["חָבֵר שָׁכַח אֶת הַכֶּסֶף לָאוֹטוֹבּוּס, וּמְבַקֵּשׁ שֶׁתַּלְוֶה לוֹ. מָה עוֹשִׂים?",["מַלְוִים לוֹ בְּשִׂמְחָה","שׁוֹלְחִים אוֹתוֹ לְבַקֵּשׁ מֵאַחֵר","נוֹזְפִים בּוֹ שֶׁשָּׁכַח"],0,"מִצְוַת עֲשֵׂה מִן הַתּוֹרָה לְהַלְווֹת לְמִי שֶׁצָּרִיךְ, וְהִיא מֻטֶּלֶת עַל כָּל אֶחָד מִיִּשְׂרָאֵל – גַּם עָלֶיךָ. וּמַלְוִים בְּשִׂמְחָה, בְּלִי לְבַיֵּשׁ.","פֶּרֶק ה׳, הֲלָכוֹת א׳, ו׳","מַלְוִים וְנוֹתְנִים"],["דָּנִי לָוָה כֶּסֶף, וְלֹא קָבְעוּ מָתַי לְהַחֲזִיר. מָתַי עָלָיו לְהַחֲזִיר?",["כְּשֶׁיִּהְיֶה לוֹ חֵשֶׁק","אַחֲרֵי שְׁלוֹשִׁים יוֹם","רַק כְּשֶׁיַּזְכִּירוּ לוֹ"],1,"הַלְוָאָה סְתָמִית הִיא לִשְׁלוֹשִׁים יוֹם: אִם לֹא סִכְּמוּ מוֹעֵד, מַחֲזִירִים אַחֲרֵי שְׁלוֹשִׁים יוֹם, בְּלִי לְחַכּוֹת שֶׁיַּזְכִּירוּ.","פֶּרֶק ה׳, הֲלָכָה ג׳","מַלְוִים וְנוֹתְנִים"],["יוֹסִי הֶחֱזִיר לְךָ אֶתְמוֹל הַלְוָאָה, וְהַיּוֹם הוּא מְבַקֵּשׁ שׁוּב. מָה עוֹשִׂים?",["אוֹמְרִים: כְּבָר הִלְוֵיתִי לְךָ","מַלְוִים – אֲבָל בְּפַרְצוּף חָמוּץ","מַלְוִים לוֹ שׁוּב בְּשִׂמְחָה"],2,"מַלְוִים שׁוּב וְשׁוּב, אֲפִלּוּ מֵאָה פְּעָמִים, מִתּוֹךְ שִׂמְחָה וְחִבָּה – כְּמוֹ בַּעַל חֲנוּת שֶׁשָּׂמֵחַ בְּכָל קוֹנֶה, כִּי בְּכָל הַלְוָאָה מַרְוִיחִים מִצְוָה.","פֶּרֶק ה׳, הֲלָכָה ג׳","מַלְוִים וְנוֹתְנִים"],["אַתָּה מַלְוֶה לְחָבֵר עֲשָׂרָה שְׁקָלִים. כַּמָּה מֻתָּר לְבַקֵּשׁ שֶׁיַּחֲזִיר?",["שְׁנֵים עָשָׂר שְׁקָלִים","עֲשָׂרָה שְׁקָלִים","חֲמִשָּׁה עָשָׂר שְׁקָלִים"],1,"מְבַקְשִׁים בְּדִיּוּק אֶת מָה שֶׁהִלְוִינוּ. כָּל תּוֹסֶפֶת הִיא רִבִּית, וְהִיא אֲסוּרָה גַּם לַמַּלְוֶה, גַּם לַלּוֹוֶה וְגַם לָעֵדִים.","פֶּרֶק ה׳, הֲלָכָה ד׳","מַלְוִים וְנוֹתְנִים"],["הִלְוֵיתָ לְחָבֵר כַּמָּה שְׁקָלִים. מָה כְּדַאי לַעֲשׂוֹת, כְּדֵי שֶׁלֹּא יִהְיֶה אַחַר כָּךְ רִיב?",["לִרְשֹׁם אֶת הַהַלְוָאָה בְּפִנְקָס","לְהַזְכִּיר לוֹ כָּל שָׁעָה","לְסַפֵּר עַל כָּךְ לְכָל הַכִּתָּה"],0,"גַּם אָדָם הָגוּן עָלוּל לִשְׁכֹּחַ. לָכֵן כּוֹתְבִים אֶת הַהַלְוָאָה – אוֹ מַחְלִיטִים מֵרֹאשׁ בַּלֵּב לִמְחֹל אִם יִשְׁכַּח. כָּךְ לֹא יִהְיֶה רִיב.","פֶּרֶק ה׳, הֲלָכָה ח׳","מַלְוִים וְנוֹתְנִים"],["עָנִי דּוֹפֵק בַּדֶּלֶת וּמְבַקֵּשׁ צְדָקָה. מָה נוֹתְנִים לוֹ?",["שׁוֹלְחִים אוֹתוֹ בְּלִי כְּלוּם","אֶת כָּל הַחִסָּכוֹן","מַטְבֵּעַ קָטָן"],2,"לְעָנִי שֶׁעוֹבֵר בֵּין הַבָּתִּים נוֹתְנִים מַתָּנָה קְטַנָּה – לֹא סְכוּם גָּדוֹל, אֲבָל גַּם לֹא שׁוֹלְחִים אוֹתוֹ רֵיקָם.","פֶּרֶק ו׳, הֲלָכָה ד׳","מַלְוִים וְנוֹתְנִים"],["סַבָּא נָתַן לְךָ חֲמִשִּׁים שְׁקָלִים בְּמַתָּנָה. מָה עוֹשִׂים?",["קוֹנִים בְּכֻלָּם מַמְתַּקִּים","שָׂמִים חֲמִשָּׁה שְׁקָלִים בַּקֻּפָּה","מַחְבִּיאִים אֶת הַכֹּל בַּמְּגֵרָה"],1,"גַּם מִכֶּסֶף שֶׁקִּבַּלְנוּ בְּמַתָּנָה מַפְרִישִׁים מַעֲשֵׂר – אֶחָד מִכָּל עֲשָׂרָה. מֵחֲמִשִּׁים שְׁקָלִים, הַמַּעֲשֵׂר הוּא חֲמִשָּׁה.","פֶּרֶק ו׳, הֲלָכָה ט׳","מַלְוִים וְנוֹתְנִים"],["אֵיזוֹ צְדָקָה הִיא הַמַּעֲלָה הַגְּבוֹהָה בְּיוֹתֵר?",["לָתֵת לֶעָנִי כִּכַּר לֶחֶם","לָתֵת לוֹ מַטְבֵּעַ","לַעֲזֹר לוֹ לִמְצֹא עֲבוֹדָה"],2,"הַמַּעֲלָה הַגְּבוֹהָה בְּיוֹתֵר הִיא לַעֲזֹר לֶעָנִי לַעֲמֹד עַל רַגְלָיו – לִמְצֹא עֲבוֹדָה אוֹ לִלְמֹד מִקְצוֹעַ – כְּדֵי שֶׁיִּתְפַּרְנֵס בְּכָבוֹד וְלֹא יִצְטָרֵךְ לְבַקֵּשׁ.","פֶּרֶק ו׳, הֲלָכָה א׳","מַלְוִים וְנוֹתְנִים"],["שְׁנַיִם מְבַקְשִׁים הַלְוָאָה, וְיֵשׁ לְךָ רַק לְאֶחָד: עָנִי וְעָשִׁיר. לְמִי מַלְוִים?",["לֶעָנִי","לֶעָשִׁיר, כִּי בָּטוּחַ שֶׁיַּחֲזִיר","לְמִי שֶׁבִּקֵּשׁ רִאשׁוֹן"],0,"\"אֶת הֶעָנִי עִמָּךְ\" – הַתּוֹרָה צִוְּתָה לְהַקְדִּים אֶת הֶעָנִי, כִּי הוּא צָרִיךְ יוֹתֵר. בְּלִי הַצִּוּוּי הָיוּ רַבִּים מַעֲדִיפִים אֶת הֶעָשִׁיר, שֶׁבָּטוּחַ יוֹתֵר.","פֶּרֶק ה׳, הֲלָכוֹת א׳, י״א","מַלְוִים וְנוֹתְנִים"],["שְׁנֵי עֲנִיִּים: אֶחָד צָרִיךְ אֹכֶל, וְהַשֵּׁנִי צָרִיךְ בְּגָדִים חֲדָשִׁים. לְמִי עוֹזְרִים קֹדֶם?",["לְמִי שֶׁצָּרִיךְ בְּגָדִים","לְמִי שֶׁצָּרִיךְ אֹכֶל","לְמִי שֶׁמְּבַקֵּשׁ בְּקוֹל חָזָק"],1,"מִי שֶׁצָּרִיךְ יוֹתֵר – קוֹדֵם. לָכֵן מִי שֶׁצָּרִיךְ אֹכֶל קוֹדֵם לְמִי שֶׁצָּרִיךְ בְּגָדִים, וּמִי שֶׁצָּרִיךְ בְּגָדִים קוֹדֵם לְמִי שֶׁצָּרִיךְ רָהִיטִים.","פֶּרֶק ה׳, הֲלָכָה י״ג; פֶּרֶק ו׳, הֲלָכָה ה׳","מַלְוִים וְנוֹתְנִים"],["אוֹרֵחַ עָיֵף מַגִּיעַ לַבַּיִת שֶׁלָּכֶם. מָה עוֹשִׂים קֹדֶם?",["מַגִּישִׁים לוֹ שְׁתִיָּה וְאֹכֶל","מַרְאִים לוֹ אֶת כָּל הַבַּיִת","מְחַכִּים שֶׁיְּבַקֵּשׁ מַשֶּׁהוּ"],0,"מִיָּד כְּשֶׁהָאוֹרֵחַ מַגִּיעַ מַגִּישִׁים לוֹ אֹכֶל וּשְׁתִיָּה, כִּי אוּלַי הוּא רָעֵב וְצָמֵא וּמִתְבַּיֵּשׁ לְבַקֵּשׁ.","פֶּרֶק ז׳, הֲלָכָה ה׳","אוֹרְחִים וַחֲבֵרִים"],["מָה עָשָׂה אַבְרָהָם אָבִינוּ כְּשֶׁהָיָה חוֹלֶה וְרָאָה אוֹרְחִים?",["נָח בָּאֹהֶל עַד שֶׁיַּבְרִיא","רָץ לִקְרָאתָם בְּשִׂמְחָה","בִּקֵּשׁ שֶׁיָּבוֹאוּ בְּיוֹם אַחֵר"],1,"אַבְרָהָם יָצָא לְחַפֵּשׂ אוֹרְחִים גַּם בִּהְיוֹתוֹ חוֹלֶה, וּכְשֶׁרָאָה אוֹתָם – שָׁכַח אֶת מַחֲלָתוֹ וְרָץ לִקְרָאתָם.","פֶּרֶק ז׳, הֲלָכָה א׳","אוֹרְחִים וַחֲבֵרִים"],["אוֹרֵחַ מְבַקֵּשׁ כּוֹס מַיִם. מָה הֲכִי דּוֹמֶה לְמַעֲשֵׂה רִבְקָה?",["מַרְאִים לוֹ אֵיפֹה הַבֶּרֶז","נוֹתְנִים כּוֹס – וְהוֹלְכִים","נוֹתְנִים מַיִם וּמַצִּיעִים עוֹד"],2,"רִבְקָה לֹא הִסְתַּפְּקָה בְּמָה שֶׁבִּקְּשׁוּ מִמֶּנָּה – הִיא הִצִּיעָה מֵעַצְמָהּ לְהַשְׁקוֹת גַּם אֶת הַגְּמַלִּים. כָּךְ עוֹשֶׂה בַּעַל חֶסֶד אֲמִתִּי.","פֶּרֶק ז׳, הֲלָכָה ב׳","אוֹרְחִים וַחֲבֵרִים"],["יֶלֶד חָדָשׁ עוֹמֵד לְבַד בַּהַפְסָקָה. מָה עוֹשִׂים?",["מַמְשִׁיכִים לְשַׂחֵק כָּרָגִיל","מַזְמִינִים אוֹתוֹ לְשַׂחֵק אִתָּנוּ","מִסְתַּכְּלִים עָלָיו מֵרָחוֹק"],1,"מִי שֶׁמַּרְגִּישׁ בּוֹדֵד צָרִיךְ חֹם וְעִדּוּד. אַשְׁרֵי מִי שֶׁיּוֹדֵעַ לִרְאוֹת מִי זָקוּק לְעִדּוּד – וּמַזְמִין אוֹתוֹ.","פֶּרֶק ז׳, הֲלָכוֹת ו׳–ז׳","אוֹרְחִים וַחֲבֵרִים"],["אוֹרֵחַ נִשְׁאָר לִישֹׁן אֶצְלְכֶם בְּלֵיל חֹרֶף. מָה מְכִינִים לוֹ?",["מִטָּה מִתְקַפֶּלֶת שֶׁחוֹרֶקֶת","מִזְרָן עַל הָרִצְפָּה בְּלִי כַּר","מִטָּה נוֹחָה עִם שְׂמִיכָה חַמָּה"],2,"לִפְעָמִים שֵׁנָה טוֹבָה חֲשׁוּבָה לָאוֹרֵחַ יוֹתֵר מֵאֲרוּחָה טוֹבָה. מְכִינִים לוֹ מִטָּה נוֹחָה, כַּר וּשְׂמִיכָה חַמָּה.","פֶּרֶק ז׳, הֲלָכָה ח׳","אוֹרְחִים וַחֲבֵרִים"],["הָאוֹרֵחַ הוֹלֵךְ הַבַּיְתָה. מָה עוֹשִׂים?",["מְלַוִּים אוֹתוֹ כַּמָּה צְעָדִים בַּחוּץ","מְנַפְנְפִים לוֹ מִן הַסַּפָּה","סוֹגְרִים מַהֵר אֶת הַדֶּלֶת"],0,"מְלַוִּים אֶת הָאוֹרֵחַ לְפָחוֹת אַרְבַּע אַמּוֹת מִחוּץ לַבַּיִת – כְּאַרְבָּעָה צְעָדִים. כָּךְ הוּא יוֹדֵעַ שֶׁשָּׂמְחוּ בּוֹ בֶּאֱמֶת.","פֶּרֶק ז׳, הֲלָכָה י״א","אוֹרְחִים וַחֲבֵרִים"],["אַתָּה מְחַלֵּק הַזְמָנוֹת לְבַר הַמִּצְוָה שֶׁלְּךָ. אֶת מִי לֹא שׁוֹכְחִים?",["רַק אֶת הַחֲבֵרִים הֲכִי טוֹבִים","אֶת הַשָּׁכֵן הַזָּקֵן הַבּוֹדֵד","רַק מִי שֶׁיָּבִיא מַתָּנָה יָפָה"],1,"כְּשֶׁעוֹרְכִים שִׂמְחָה, חוֹשְׁבִים קֹדֶם עַל הַבּוֹדְדִים וְהָעֲנִיִּים, וְלֹא שׁוֹכְחִים לְהַזְמִין אוֹתָם. רַק כָּךְ הַשִּׂמְחָה אֲמִתִּית.","פֶּרֶק ז׳, הֲלָכָה י״ב","אוֹרְחִים וַחֲבֵרִים"],["עִם אֵיזֶה חָבֵר כְּדַאי לְהִתְחַבֵּר?",["עִם מִי שֶׁצּוֹחֵק עַל אֲחֵרִים","עִם מִי שֶׁמִּתְחַצֵּף לַמּוֹרִים","עִם מִי שֶׁלּוֹמֵד וְעוֹזֵר לַאֲחֵרִים"],2,"חָבֵר טוֹב מַשְׁפִּיעַ עָלֶיךָ לְטוֹבָה, כְּמוֹ רֵיחַ טוֹב שֶׁל חֲנוּת בְּשָׂמִים. וּמִמּוֹשַׁב לֵצִים – מִתְרַחֲקִים.","פֶּרֶק י״ז, הֲלָכָה א׳","אוֹרְחִים וַחֲבֵרִים"],["אַתָּה מִתְאָרֵחַ אֵצֶל חָבֵר. מָה מַתְאִים לְאוֹרֵחַ טוֹב?",["עוֹזֵר לְסַדֵּר וְלֹא מַטְרִיחַ","מְבַקֵּשׁ כָּל רֶגַע מַשֶּׁהוּ חָדָשׁ","מַחְלִיט לְהִשָּׁאֵר עוֹד שָׁבוּעַ"],0,"אוֹרֵחַ טוֹב מִשְׁתַּדֵּל לֹא לְהַטְרִיחַ וְלֹא לְהַכְבִּיד. \"הֹקַר רַגְלְךָ מִבֵּית רֵעֶךָ\" – כְּדֵי שֶׁכָּל בִּקּוּר יִשָּׁאֵר יָקָר.","פֶּרֶק ז׳, הֲלָכָה ט׳","אוֹרְחִים וַחֲבֵרִים"],["מָה עָלוּל לְהַשְׁפִּיעַ עָלֵינוּ הַיּוֹם אֲפִלּוּ יוֹתֵר מִשָּׁכֵן רָע?",["כַּדּוּר בֶּחָצֵר","מָסָךְ וּכְלֵי תִּקְשֹׁרֶת","שָׁכֵן שֶׁאֵין לָנוּ קֶשֶׁר אִתּוֹ"],1,"כְּלֵי הַתִּקְשֹׁרֶת עֲלוּלִים לְהַשְׁפִּיעַ יוֹתֵר מִכָּל שָׁכֵן רָע. וְשָׁכֵן שֶׁאֵין לָנוּ קֶשֶׁר אִתּוֹ מַשְׁפִּיעַ פָּחוֹת – הַחֲבֵרִים שֶׁבּוֹחֲרִים חֲשׁוּבִים יוֹתֵר.","פֶּרֶק י״ז, הֲלָכָה ד׳","אוֹרְחִים וַחֲבֵרִים"],["לְבֵית מִשְׁפַּחַת כֹּהֵן יֵשׁ גַּג שֶׁעוֹלִים אֵלָיו בְּמַדְרֵגוֹת. אֵיךְ הוּא צָרִיךְ לְהֵרָאוֹת?",["גַּג בְּלִי שׁוּם מַעֲקֶה","גַּג עִם קִיר נָמוּךְ כְּמוֹ סַפְסָל","גַּג עִם מַעֲקֶה גָּבוֹהַּ וְחָזָק"],2,"גַּג שֶׁעוֹלִים אֵלָיו חַיָּב בְּמַעֲקֶה גָּבוֹהַּ וְחָזָק. קִיר בְּגֹבַהּ סַפְסָל אֵינוֹ מַעֲקֶה – יְלָדִים עֲלוּלִים לַעֲמֹד עָלָיו.","פֶּרֶק ט׳, הֲלָכוֹת א׳, ג׳, ה׳","שׁוֹמְרִים עַל הַחַיִּים"],["בַּבַּיִת יֵשׁ בַּקְבּוּק אֶקוֹנוֹמִיקָה. אֵיפֹה שׁוֹמְרִים אוֹתוֹ?",["בְּאָרוֹן גָּבוֹהַּ וְסָגוּר","בְּבַקְבּוּק מִיץ רֵיק","עַל הָרִצְפָּה, לְיַד הַקְּטַנִּים"],0,"חֹמֶר רַעַל שׁוֹמְרִים בְּמָקוֹם שֶׁקְּטַנִּים לֹא מַגִּיעִים אֵלָיו, וְלֹא בְּבַקְבּוּק שֶׁשּׁוֹתִים מִמֶּנּוּ – שֶׁמָּא מִישֶׁהוּ יִשְׁתֶּה מִמֶּנּוּ בְּטָעוּת.","פֶּרֶק ט׳, הֲלָכָה ז׳","שׁוֹמְרִים עַל הַחַיִּים"],["מָצָאתָ בַּמַּחְסָן סֻלָּם רָעוּעַ. מָה עוֹשִׂים?",["מַשְׁאִירִים אוֹתוֹ בַּמָּקוֹם","מְסַפְּרִים לְאַבָּא, וּמְתַקְּנִים אוֹ זוֹרְקִים","מְטַפְּסִים עָלָיו לְאַט"],1,"אָסוּר לְהַשְׁאִיר בַּבַּיִת סֻלָּם רָעוּעַ – מִי שֶׁלֹּא יוֹדֵעַ עָלוּל לַעֲלוֹת עָלָיו וְלִפֹּל. מְתַקְּנִים אוֹתוֹ אוֹ מוֹצִיאִים אוֹתוֹ מִן הַבַּיִת.","פֶּרֶק ט׳, הֲלָכוֹת ג׳, ז׳","שׁוֹמְרִים עַל הַחַיִּים"],["בֶּחָצֵר יֵשׁ בּוֹר עָמֹק וְרֵיק. מָה הַדִּין?",["מְכַסִּים אוֹתוֹ בְּמִכְסֶה חָזָק","מְסַמְּנִים אוֹתוֹ בְּאֶבֶן קְטַנָּה","מַשְׁאִירִים, כִּי אֵין בּוֹ מַיִם"],0,"בּוֹר עָמֹק בֶּחָצֵר מְכַסִּים אוֹ מַקִּיפִים בְּמַעֲקֶה – גַּם כְּשֶׁאֵין בּוֹ מַיִם, כִּי אֶפְשָׁר לִפֹּל לְתוֹכוֹ.","פֶּרֶק ט׳, הֲלָכָה ו׳","שׁוֹמְרִים עַל הַחַיִּים"],["נִכְנָסִים לָרֶכֶב לִנְסִיעָה. מָה עוֹשִׂים קֹדֶם כָּל דָּבָר?",["עוֹמְדִים בֵּין הַמּוֹשָׁבִים","חוֹגְרִים חֲגוֹרַת בְּטִיחוּת","יוֹשְׁבִים בְּלִי לַחֲגֹר"],1,"חֻקֵּי הַבְּטִיחוּת נִקְבְּעוּ כְּדֵי לִשְׁמֹר עַל הַחַיִּים, וּמִי שֶׁעוֹבֵר עֲלֵיהֶם עוֹבֵר עַל מִצְוַת הַתּוֹרָה – גַּם אִם לֹא קָרָה כְּלוּם.","פֶּרֶק י׳, הֲלָכָה א׳","שׁוֹמְרִים עַל הַחַיִּים"],["נַעַר גָּדוֹל מַצִּיעַ לְךָ סִיגַרְיָה \"רַק לְנַסּוֹת\". מָה עוֹשִׂים?",["מְנַסִּים פַּעַם אַחַת בִּלְבַד","שׁוֹמְרִים אוֹתָהּ בַּכִּיס","מְסָרְבִים בְּתוֹקֶף"],2,"אָסוּר מִן הַתּוֹרָה לְעַשֵּׁן. לִפְנֵי שֶׁמִּתְרַגְּלִים קַל לֹא לְהַתְחִיל, וְאַחֲרֵי שֶׁמִּתְמַכְּרִים – קָשֶׁה מְאוֹד לְהַפְסִיק. לָכֵן לֹא מַתְחִילִים אֲפִלּוּ \"רַק לְנַסּוֹת\".","פֶּרֶק ט׳, הֲלָכוֹת ח׳, י״ג","שׁוֹמְרִים עַל הַחַיִּים"],["חָבֵר בַּצַּד הֶעָמֹק שֶׁל הַבְּרֵכָה קוֹרֵא לְעֶזְרָה, וְאַתָּה לֹא יוֹדֵעַ לִשְׂחוֹת. מָה עוֹשִׂים?",["קוֹפְצִים מִיָּד לַמַּיִם","קוֹרְאִים בְּקוֹל לַמַּצִּיל","הוֹלְכִים, כִּי זֶה לֹא עִנְיָנֵנוּ"],1,"\"לֹא תַעֲמֹד עַל דַּם רֵעֶךָ\" – אָסוּר לָלֶכֶת. אֲבָל מִי שֶׁאֵינוֹ יוֹדֵעַ לִשְׂחוֹת לֹא נִכְנָס לְסַכָּנָה מַמָּשִׁית – הוּא מַצִּיל בַּדֶּרֶךְ שֶׁיֵּשׁ לוֹ: קוֹרֵא מִיָּד בְּקוֹל לַמַּצִּיל.","פֶּרֶק י׳, הֲלָכָה ד׳; פֶּרֶק י״א, הֲלָכוֹת א׳–ג׳","שׁוֹמְרִים עַל הַחַיִּים"],["בְּיוֹם חַם מְאוֹד, אִישׁ זָקֵן מַרְגִּישׁ חַלָּשׁ וְצָמֵא. יֵשׁ לְךָ בַּקְבּוּק מַיִם. מָה עוֹשִׂים?",["נוֹתְנִים לוֹ אֶת הַבַּקְבּוּק","שׁוֹתִים בְּעַצְמֵנוּ, כִּי הוּא שֶׁלָּנוּ","מַמְשִׁיכִים לָלֶכֶת"],0,"מַצִּילִים גַּם בְּמָמוֹן: אִם חֵפֶץ שֶׁלְּךָ יָכוֹל לַעֲזֹר לְמִי שֶׁבְּצָרָה – נוֹתְנִים אוֹתוֹ. וְאִם צָרִיךְ – קוֹרְאִים מִיָּד לִמְבֻגָּרִים.","פֶּרֶק י״א, הֲלָכָה ו׳","שׁוֹמְרִים עַל הַחַיִּים"],["אַתָּה רוֹאֶה מִישֶׁהוּ לוֹקֵחַ בְּשֶׁקֶט תִּיק שֶׁל חָבֵר מֵהַסַּפְסָל. מָה עוֹשִׂים?",["שׁוֹתְקִים, זֶה לֹא הַתִּיק שֶׁלִּי","צוֹעֲקִים \"גַּנָּב!\" וְקוֹרְאִים לִמְבֻגָּרִים","רָצִים לְהִתְקוֹטֵט אִתּוֹ"],1,"מִצְוָה לְהַצִּיל גַּם אֶת הָרְכוּשׁ שֶׁל חָבֵר. מִי שֶׁאֵינוֹ יָכוֹל לַעֲצֹר אֶת הַגַּנָּב – צוֹעֵק בְּכָל כֹּחוֹ \"גַּנָּב!\" כְּדֵי לְהַזְעִיק אֲנָשִׁים. אֲבָל לֹא מִסְתַּכְּנִים בִּשְׁבִיל מָמוֹן.","פֶּרֶק י״א, הֲלָכָה ח׳","שׁוֹמְרִים עַל הַחַיִּים"],["מָתַי אוֹמְרִים תְּפִלַּת הַדֶּרֶךְ?",["בַּנְּסִיעָה לַמַּכֹּלֶת שֶׁבַּשְּׁכוּנָה","בְּתוֹךְ הַבַּיִת, לִפְנֵי שֶׁיּוֹצְאִים","כְּשֶׁיּוֹצְאִים מִן הָעִיר לִנְסִיעָה אֲרֻכָּה"],2,"אוֹמְרִים תְּפִלַּת הַדֶּרֶךְ עַל דֶּרֶךְ שֶׁל יוֹתֵר מִפַּרְסָה – כְּאַרְבָּעָה קִילוֹמֶטְרִים – מִיָּד אַחֲרֵי הַיְּצִיאָה מִן הָעִיר. בִּלְשׁוֹן רַבִּים, כְּשֶׁמִּשְׁתַּתְּפִים עִם כָּל הַצִּבּוּר.","פֶּרֶק י׳, הֲלָכוֹת ו׳, ח׳–ט׳","שׁוֹמְרִים עַל הַחַיִּים"]],"b":[["שִׁמְעוֹן לֹא הִשְׁאִיל לִרְאוּבֵן אֶת הָאוֹפַנַּיִם. לְמָחֳרָת שִׁמְעוֹן מְבַקֵּשׁ כַּדּוּר, וּרְאוּבֵן נוֹתֵן וְאוֹמֵר: \"תִּרְאֶה שֶׁאֲנִי לֹא כָּמוֹךָ\". מָה הַדִּין?",["עָבַר עַל לֹא תִטֹּר, כִּי הוֹסִיף עֲקִיצָה","לֹא עָבַר עַל שׁוּם אִסּוּר, כִּי בְּסוֹף הוּא הִשְׁאִיל","עָבַר עַל לֹא תִקֹּם, כִּי הוּא נָקַם בְּשִׁמְעוֹן","עָשָׂה מִצְוָה, כִּי לִמֵּד אֶת שִׁמְעוֹן מוּסָר חָשׁוּב"],0,"הוּא לֹא נָקַם, כִּי הִשְׁאִיל. אֲבָל כָּל לַעַג שֶׁקָּשׁוּר לְמָה שֶׁהָיָה אֶתְמוֹל הוּא נְטִירָה. צָרִיךְ לִמְחוֹת אֶת הַכַּעַס מִן הַלֵּב.","פֶּרֶק א׳, הֲלָכָה ו׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אַרְיֵה פָּגַע בְּדָוִד, וְדָוִד כּוֹעֵס עָלָיו. מָה הַדֶּרֶךְ שֶׁהַתּוֹרָה מַעְדִּיפָה?",["לְהַסְתִּיר אֶת הַכַּעַס וּלְחַכּוֹת לְהִזְדַּמְּנוּת לְהַחְזִיר","לְהִתְנַהֵג אֵלָיו בְּנִימוּס, וְלִשְׁמֹר אֶת הַכַּעַס בְּתוֹךְ הַלֵּב","לְדַבֵּר אִתּוֹ בְּנַחַת וּלְבָרֵר לָמָּה עָשָׂה לוֹ כָּךְ","לְסַפֵּר לְכָל הַכִּתָּה מָה אַרְיֵה עָשָׂה לוֹ"],2,"הַתּוֹרָה רוֹצָה שִׂיחָה כֵּנָה: \"לָמָּה עָשִׂיתָ לִי כָּךְ?\". שְׁתִיקָה עִם שִׂנְאָה בַּלֵּב הִיא מִנְהַג הָרְשָׁעִים, וְסִפּוּר לְכָל הַכִּתָּה הוּא לָשׁוֹן הָרָע.","פֶּרֶק א׳, הֲלָכוֹת ד׳, ו׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["רָאִיתָ אֶת רַב בֵּית הַכְּנֶסֶת, אִישׁ יְרֵא שָׁמַיִם, יוֹצֵא בְּאֶמְצַע הַתְּפִלָּה. מָה נָכוֹן לַחְשֹׁב?",["לְהָבִין לְטוֹבָה רַק אִם הַהֶסְבֵּר הַטּוֹב סָבִיר מְאוֹד","לְחַפֵּשׂ לוֹ הֶסְבֵּר טוֹב, גַּם אִם הוּא דָּחוּק","לֹא לַחְשֹׁב כְּלוּם, כִּי אָסוּר לִשְׁפֹּט אֲפִלּוּ לְטוֹבָה","לַחְשֹׁב שֶׁהוּא מְזַלְזֵל, כִּי כָּךְ זֶה נִרְאֶה"],1,"אֵצֶל אָדָם צַדִּיק, כָּל זְמַן שֶׁאֶפְשָׁר לְפָרֵשׁ לְטוֹבָה – אֲפִלּוּ בְּהֶסְבֵּר דָּחוּק – מִצְוָה לָדוּן אוֹתוֹ לְכַף זְכוּת. \"הַחוֹשֵׁד בִּכְשֵׁרִים לוֹקֶה בְּגוּפוֹ\".","פֶּרֶק א׳, הֲלָכָה י׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["נֹעַם רוֹצֶה לְהַחְלִיף קְלָפִים עִם יֶלֶד שֶׁאַתָּה יוֹדֵעַ שֶׁהוּא נוֹטֶה לְרַמּוֹת. מָה עוֹשִׂים?",["מְסַפְּרִים לְכָל הַכִּתָּה, כְּדֵי שֶׁכֻּלָּם יִזָּהֲרוּ מִמֶּנּוּ","שׁוֹתְקִים, כִּי כָּל דָּבָר רַע עַל יֶלֶד הוּא לָשׁוֹן הָרָע","מְחַכִּים שֶׁנֹּעַם יִשְׁאַל, כִּי בְּלִי שְׁאֵלָה אָסוּר לְסַפֵּר","מַזְהִירִים אֶת נֹעַם בְּלִי לְהַגְזִים, כְּדֵי לְהַצִּיל אוֹתוֹ"],3,"כְּדֵי לְהַצִּיל חָבֵר מִלִּפֹּל בַּפַּח – צָרִיךְ לְהַזְהִיר אוֹתוֹ, גַּם אִם לֹא שָׁאַל. אֲבָל רַק בְּכַוָּנָה טְהוֹרָה, וּבְלִי לְהַגְזִים.","פֶּרֶק א׳, הֲלָכָה י״ג","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["חָבֵר בָּעַט בְּכַדּוּר וְשָׁבַר חַלּוֹן בַּמּוֹעֲדוֹן שֶׁל הַיִּשּׁוּב. כָּל הַחֲבֵרִים הֶחְלִיטוּ לִשְׁתֹּק. מָה נָכוֹן?",["לְשַׁכְנֵעַ אוֹתוֹ לְשַׁלֵּם, וְאִם יְסָרֵב – לְסַפֵּר לָאַחְרָאִים","לִשְׁתֹּק עִם כֻּלָּם, כִּי לְהַלְשִׁין זֶה לָשׁוֹן הָרָע","לִשְׁתֹּק, כִּי הוּא שָׁבַר בְּלִי כַּוָּנָה וְלֹא חַיָּב","לְסַפֵּר מִיָּד לְכָל הַיִּשּׁוּב, כְּדֵי שֶׁיִּתְבַּיֵּשׁ"],0,"מִי שֶׁהִזִּיק חַיָּב לְשַׁלֵּם, גַּם בְּלִי כַּוָּנָה. מְנַסִּים קֹדֶם לְשַׁכְנֵעַ אוֹתוֹ, וְאִם לֹא – מְסַפְּרִים לָאַחְרָאִים. זוֹ הַצָּלַת מָמוֹן הַצִּבּוּר, וְאֵין בָּזֶה לָשׁוֹן הָרָע.","פֶּרֶק א׳, הֲלָכָה כ״א","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["לָמָּה הַתּוֹרָה הוֹסִיפָה מִצְוָה מְיֻחֶדֶת לֶאֱהֹב אֶת הַגֵּר וּלְהִזָּהֵר בַּדִּבּוּר אִתּוֹ?",["כִּי גֵּר יוֹדֵעַ תּוֹרָה פָּחוֹת, וְצָרִיךְ לְלַמֵּד אוֹתוֹ","כִּי הַגֵּרִים בָּאוּ מֵאֶרֶץ רְחוֹקָה וְאֵין לָהֶם קְרוֹבִים","כִּי הוּא בָּחַר לְהִצְטָרֵף, וְהוּא עָלוּל לִהְיוֹת רָגִישׁ יוֹתֵר","כִּי הַמִּצְוָה לֶאֱהֹב כָּל יְהוּדִי אֵינָהּ חָלָה עַל גֵּר"],2,"הַגֵּר עָשָׂה מַעֲשֶׂה גָּדוֹל – בָּחַר לְהִצְטָרֵף לְיִשְׂרָאֵל. וְהוּא עָלוּל לְהִפָּגַע מַהֵר יוֹתֵר, וְלָכֵן שׁוֹקְלִים כָּל מִלָּה. גַּם הַמִּצְוָה \"וְאָהַבְתָּ לְרֵעֲךָ\" חָלָה עָלָיו.","פֶּרֶק א׳, הֲלָכָה ט״ו","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["הַכִּתָּה מְתַכְנֶנֶת לְהֵעָלֵם לִפְנֵי הַשִּׁעוּר הָאַחֲרוֹן, כְּדֵי לִצְחֹק עַל הַמּוֹרֶה. מָה עוֹשִׂים?",["בּוֹרְחִים עִם כֻּלָּם, כְּדֵי לִשְׁמֹר עַל אַחְדוּת הַכִּתָּה","נִשְׁאָרִים, וּמְנַסִּים לְשַׁכְנֵעַ עוֹד חֲבֵרִים לְהִשָּׁאֵר","נִשְׁאָרִים לְבַד בְּשֶׁקֶט, וְלֹא אוֹמְרִים לְאַף אֶחָד דָּבָר","בּוֹרְחִים, אֲבָל מְבַקְּשִׁים מֵהַמּוֹרֶה סְלִיחָה לְמָחֳרָת"],1,"הַתַּעֲלוּל מַלְבִּין אֶת פְּנֵי הַמּוֹרֶה. אַחְדוּת טוֹבָה רַק כְּשֶׁהִיא לַטּוֹב – לָכֵן נִשְׁאָרִים בִּגְבוּרָה וּמְנַסִּים לְשַׁכְנֵעַ כְּמָה שֶׁיּוֹתֵר חֲבֵרִים לְהִשָּׁאֵר.","פֶּרֶק א׳, הֲלָכָה כ״ב","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["בַּכִּתָּה יֵשׁ וִכּוּחַ עַל פֵּרוּשׁ שֶׁל פָּסוּק. מָתַי זוֹ \"מַחֲלֹקֶת לְשֵׁם שָׁמַיִם\"?",["כְּשֶׁכָּל צַד מְנַסֶּה לְנַצֵּחַ בְּכָל מְחִיר וּלְבַיֵּשׁ אֶת הַשֵּׁנִי","כְּשֶׁכֻּלָּם מַסְכִּימִים מִיָּד, וְאֵין בִּכְלָל וִכּוּחַ","כְּשֶׁהַוִּכּוּחַ נִמְשָׁךְ זְמַן רַב, וְכָל קְבוּצָה עוֹמֶדֶת עַל שֶׁלָּהּ","כְּשֶׁמִּתְוַכְּחִים עַל הָעִנְיָן, בְּלִי שִׂנְאָה אִישִׁית"],3,"מַחֲלֹקֶת עִנְיָנִית בְּלִי שִׂנְאָה, כְּמוֹ שֶׁל הִלֵּל וְשַׁמַּאי, מְבָרֶרֶת אֶת הָאֱמֶת וְסוֹפָהּ לְהִתְקַיֵּם. מַחֲלֹקֶת שֶׁל שִׂנְאָה דּוֹמָה לְשֶׁל קֹרַח וַעֲדָתוֹ.","פֶּרֶק א׳, הֲלָכָה י״ח","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["הָאָח הַקָּטָן שֶׁל יוֹנָתָן הָרַס לוֹ אֶת מִגְדַּל הַקֻּבִּיּוֹת, וְיוֹנָתָן כּוֹעֵס מְאוֹד. מָה מְלַמְּדִים חֲכָמִים?",["מֻתָּר לִזְרֹק קֻבִּיָּה, כִּי הַכַּעַס שֶׁלּוֹ צוֹדֵק לְגַמְרֵי","לְהִתְאַפֵּק, כִּי הַכּוֹעֵס דּוֹמֶה לְעוֹבֵד עֲבוֹדָה זָרָה","לִשְׁבֹּר מַשֶּׁהוּ שֶׁל הָאָח, כְּדֵי שֶׁיִּלְמַד לְקַח לַפַּעַם הַבָּאָה","לִשְׁמֹר אֶת הַכַּעַס בַּלֵּב, וְלֹא לְדַבֵּר עִם הָאָח שָׁבוּעַ"],1,"חֲכָמִים אָמְרוּ שֶׁהַכּוֹעֵס דּוֹמֶה לְעוֹבֵד עֲבוֹדָה זָרָה: הַכַּעַס מַשְׁתַּלֵּט עָלָיו, וְהוּא עוֹשֶׂה דְּבָרִים שֶׁאַחַר כָּךְ יִצְטַעֵר עֲלֵיהֶם. מִתְאַפְּקִים, וְאַחַר כָּךְ מְדַבְּרִים בְּנַחַת.","פֶּרֶק ט״ז, הֲלָכָה ז׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["יֶלֶד בַּכִּתָּה הֶעֱלִיב אֶת נְרִיָּה פַּעֲמַיִם הַחֹדֶשׁ. חָבֵר אוֹמֵר: ״הוּא רָשָׁע, מֻתָּר לִשְׂנֹא אוֹתוֹ!״ מָה נָכוֹן?",["נָכוֹן, כִּי מִי שֶׁמַּעֲלִיב פַּעֲמַיִם נֶחְשָׁב כְּבָר לְרָשָׁע","לֹא נָכוֹן, כִּי מִי שֶׁנִּכְשָׁל מִפַּעַם לְפַעַם אֵינוֹ רָשָׁע","נָכוֹן, אֲבָל רַק עַד שֶׁהוּא יְבַקֵּשׁ סְלִיחָה בִּפְנֵי כֻּלָּם","לֹא נָכוֹן, כִּי מֻתָּר לִשְׂנֹא רַק מִי שֶׁגָּדוֹל מִמֶּנּוּ"],1,"מִי שֶׁנִּכְשָׁל מִפַּעַם לְפַעַם בַּחֲטָאִים שֶׁבֵּין אָדָם לַחֲבֵרוֹ – אֵינוֹ נֶחְשָׁב רָשָׁע, וְאָסוּר לִשְׂנֹא אוֹתוֹ. נְרִיָּה יְדַבֵּר אִתּוֹ בְּנַחַת וְיַגִּיד לוֹ שֶׁנִּפְגַּע – וְזוֹ הַדֶּרֶךְ לְתַקֵּן.","פֶּרֶק א׳, הֲלָכָה ה׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אַחֲרֵי שֶׁמְּשֻׁלָּם הֶעֱלִיב אוֹתוֹ, נִסָּה גִּלְעָד לְדַבֵּר אִתּוֹ כַּמָּה פְּעָמִים – וּמְשֻׁלָּם רַק צוֹחֵק וְאֵינוֹ מוּכָן לְהָבִין. מָה יַעֲשֶׂה גִּלְעָד?",["יִמְחֹק אֶת הָעֶלְבּוֹן מִלִּבּוֹ, וְיִמְחַל לוֹ בְּלִי לְדַבֵּר עוֹד","יִשְׁמֹר אֶת הַכַּעַס בַּלֵּב, אֲבָל לֹא יַגִּיד לוֹ כְּלוּם","יַעֲלִיב אוֹתוֹ בַּחֲזָרָה, כְּדֵי שֶׁיָּבִין סוֹף סוֹף מָה הִרְגִּישׁ","יְסַפֵּר לְכָל הַכִּתָּה, כְּדֵי שֶׁיִּזָּהֲרוּ מִמֶּנּוּ מֵעַכְשָׁו"],0,"הַדֶּרֶךְ הַטּוֹבָה הִיא לְדַבֵּר עִם הֶחָבֵר וּלְתַקֵּן. אֲבָל כְּשֶׁרוֹאִים שֶׁהַשִּׂיחָה לֹא תּוֹעִיל – מוֹחֲלִים לוֹ בַּלֵּב וּמוֹחֲקִים אֶת הַשִּׂנְאָה. כָּךְ כָּתַב הָרַמְבַּ״ם: זוֹ מִדַּת חֲסִידוּת, וְלֹא הִקְפִּידָה הַתּוֹרָה אֶלָּא עַל הַמַּשְׂטֵמָה – הַשִּׂנְאָה שֶׁנִּשְׁאֶרֶת בַּלֵּב.","פֶּרֶק א׳, הֲלָכָה ח׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["דָּנִי הוּא הַיֶּלֶד הֲכִי גָּדוֹל בַּחֲבוּרָה, וְהַקְּטַנִּים מִתְבַּיְּשִׁים לְסָרֵב לוֹ. הוּא שׁוֹלֵחַ אוֹתָם לְהָבִיא לוֹ שְׁתִיָּה מִן הַמִּטְבָּח. מָה הַדִּין?",["מֻתָּר, כִּי זֶה רַק דָּבָר קָטָן וְלֹא עֲבוֹדָה קָשָׁה","אָסוּר, כִּי הֵם מִתְבַּיְּשִׁים לְסָרֵב, וְזֶה לֹא לְטוֹבָתָם","מֻתָּר, אִם בְּסוֹף הַיּוֹם הוּא יוֹדֶה לָהֶם יָפֶה","אָסוּר רַק אִם הוּא שׁוֹלֵחַ אוֹתָם מִחוּץ לַבַּיִת"],1,"רַבֵּנוּ יוֹנָה כָּתַב שֶׁמִּי שֶׁחֲבֵרָיו מִתְבַּיְּשִׁים לְסָרֵב לוֹ, לֹא יְצַוֶּה עֲלֵיהֶם אֲפִלּוּ דָּבָר קָטָן – רַק כִּרְצוֹנָם וּלְטוֹבָתָם. אֶפְשָׁר לְבַקֵּשׁ בְּנִימוּס מִמִּי שֶׁבֶּאֱמֶת שָׂמֵחַ לַעֲזֹר, אוֹ לָקוּם וּלְהָבִיא בְּעַצְמוֹ.","פֶּרֶק ט״ז, הֲלָכָה א׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אוֹרֵחַ הִגִּיעַ בִּזְמַן הָאֲרוּחָה. אַבָּא יוֹדֵעַ שֶׁהוּא מְמַהֵר וִיסָרֵב, אֲבָל בְּלִבּוֹ שָׂמֵחַ לְאָרֵחַ אוֹתוֹ. מָה הַדִּין?",["אָסוּר לְהַזְמִין, כִּי בָּרוּר שֶׁהַהַזְמָנָה לֹא תִּתְקַיֵּם","מֻתָּר לְהַזְמִין פַּעַם אוֹ פַּעֲמַיִם, מִשּׁוּם דֶּרֶךְ אֶרֶץ","צָרִיךְ לְהַפְצִיר בּוֹ הַרְבֵּה, עַד שֶׁיַּסְכִּים לְהִשָּׁאֵר","אָסוּר לְהַזְמִין, אֶלָּא אִם כֵּן הוּא רָעֵב מְאוֹד"],1,"כְּשֶׁיֵּשׁ בַּלֵּב רָצוֹן לְאָרֵחַ, הַהַזְמָנָה אֵינָהּ שֶׁקֶר – וּבְלִי הַזְמָנָה הָאוֹרֵחַ עָלוּל לְהֵעָלֵב. אֲבָל לְהַפְצִיר רַק כְּדֵי לְהֵרָאוֹת אוֹהֵב – זוֹ גְּנֵבַת דַּעַת.","פֶּרֶק ג׳, הֲלָכָה ה׳","אֱמֶת וְיֹשֶׁר"],["שִׁמְעוֹן לֹא רוֹצֶה שֶׁחֲבֵרוֹ יֹאכַל אֶצְלוֹ, אֲבָל מַפְצִיר בּוֹ – כִּי הוּא יוֹדֵעַ שֶׁהֶחָבֵר יְסָרֵב. מָה הַדִּין?",["מֻתָּר, כִּי מִמֵּילָא הֶחָבֵר לֹא יֹאכַל אֶצְלוֹ","מֻתָּר, כִּי כָּךְ הֶחָבֵר מַרְגִּישׁ שֶׁאוֹהֲבִים אוֹתוֹ","מִצְוָה, כִּי זוֹ דֶּרֶךְ אֶרֶץ לְהַזְמִין כָּל אוֹרֵחַ","אָסוּר, כִּי זוֹ הַצָּגָה כְּדֵי שֶׁיַּכִּיר לוֹ טוֹבָה"],3,"הַהַפְצָרָה נוֹעֲדָה רַק לְהֵרָאוֹת כְּאוֹהֵב גָּדוֹל, וּבֶאֱמֶת הוּא לֹא רוֹצֶה. זוֹ גְּנֵבַת דַּעַת – וְכֵן מִי שֶׁשּׁוֹלֵחַ מַתָּנָה רַק כִּי יוֹדֵעַ שֶׁלֹּא יְקַבְּלוּ אוֹתָהּ.","פֶּרֶק ג׳, הֲלָכָה ה׳","אֱמֶת וְיֹשֶׁר"],["רוֹנִי יָשַׁב בַּתַּחֲנָה. דָּוִד יָרַד מֵהָאוֹטוֹבּוּס וְחָשַׁב שֶׁרוֹנִי בָּא לְקַבֵּל אוֹתוֹ, אֲבָל רוֹנִי סְתָם חִכָּה שָׁם. מָה הַדִּין?",["אֵין חוֹבָה לְתַקֵּן, כִּי דָּוִד טָעָה מֵעַצְמוֹ","חַיָּב לְתַקֵּן מִיָּד, אַחֶרֶת זוֹ גְּנֵבַת דַּעַת","אָסוּר לְתַקֵּן, כִּי אָסוּר לְצַעֵר אֶת דָּוִד","צָרִיךְ לְהַגִּיד שֶׁבָּא בִּשְׁבִילוֹ, כְּדֵי לְשַׂמֵּחַ אוֹתוֹ"],0,"גְּנֵבַת דַּעַת הִיא רַק כְּשֶׁגּוֹרְמִים לֶחָבֵר לַחְשֹׁב טוֹבָה שֶׁאֵינָהּ. כְּשֶׁהוּא טָעָה מֵעַצְמוֹ – אֵין חוֹבָה לְתַקֵּן, כְּמוֹ שֶׁאָמַר רָבָא. רַב סָפְרָא הֶעֱדִיף לוֹמַר, מִתּוֹךְ הִדּוּר בָּאֱמֶת.","פֶּרֶק ג׳, הֲלָכָה ז׳","אֱמֶת וְיֹשֶׁר"],["יְהוּדִי נוֹתֵן לְשָׁכֵן גּוֹי בַּקְבּוּק יַיִן פָּשׁוּט, וְאוֹמֵר שֶׁזֶּה יַיִן נָדִיר וְיָקָר. מָה הַדִּין?",["מֻתָּר, כִּי עַל גּוֹי לֹא חָל אִסּוּר גְּנֵבַת דַּעַת","מֻתָּר, כִּי סוֹף סוֹף הוּא קִבֵּל מַתָּנָה בְּחִנָּם","אָסוּר, כִּי גַּם דַּעְתּוֹ שֶׁל גּוֹי אָסוּר לִגְנֹב","אָסוּר רַק אִם הַגּוֹי יְגַלֶּה אַחַר כָּךְ אֶת הָאֱמֶת"],2,"כְּמוֹ בַּמַּעֲשֶׂה שֶׁל שְׁמוּאֵל וְהַתַּרְנְגֹלֶת: הַגּוֹי חוֹשֵׁב שֶׁקִּבֵּל מַתָּנָה חֲשׁוּבָה יוֹתֵר מִמָּה שֶׁקִּבֵּל בֶּאֱמֶת – וְזוֹ גְּנֵבַת דַּעַת גְּמוּרָה.","פֶּרֶק ג׳, הֲלָכָה ו׳","אֱמֶת וְיֹשֶׁר"],["חָבֵר רוֹצֶה לַעֲשׂוֹת שָׁלוֹם בֵּין שְׁנֵי יְלָדִים שֶׁרָבוּ. מָתַי מֻתָּר לוֹ לְשַׁנּוֹת מֵהָאֱמֶת?",["תָּמִיד, כִּי מִצְוַת הַשָּׁלוֹם גְּדוֹלָה מִמִּצְוַת הָאֱמֶת","רַק אִם שְׁנֵיהֶם בִּקְּשׁוּ מִמֶּנּוּ לַעֲשׂוֹת שָׁלוֹם בֵּינֵיהֶם","אַף פַּעַם, כִּי אָסוּר לְשַׁקֵּר גַּם לְמַעַן הַשָּׁלוֹם","כְּשֶׁבָּרוּר שֶׁיֵּצֵא שָׁלוֹם, וְאַף אֶחָד לֹא יִנָּזֵק"],3,"אַהֲרֹן הַכֹּהֵן שִׁנָּה כְּדֵי לְהַשְׁכִּין שָׁלוֹם. אֲבָל אִם הַשֶּׁקֶר יַזִּיק לְמִישֶׁהוּ, אוֹ שֶׁלֹּא בָּרוּר שֶׁיָּבִיא שָׁלוֹם – אָסוּר לְשַׁנּוֹת.","פֶּרֶק ב׳, הֲלָכוֹת י״ג, ט״ו","אֱמֶת וְיֹשֶׁר"],["שׁוֹאֲלִים אֶת יוֹסֵף אִם הוּא יוֹדֵעַ הֵיטֵב אֶת כָּל הַמַּסֶּכֶת, וְהוּא יוֹדֵעַ. לָמָּה מֻתָּר לוֹ לוֹמַר שֶׁלֹּא?",["כִּי בְּעִנְיְנֵי לִמּוּד מֻתָּר לְשַׁקֵּר בְּכָל מַצָּב","מִשּׁוּם עֲנָוָה – לֹא מְסַפְּרִים עַל הַמַּעֲלוֹת שֶׁל עַצְמְךָ","כִּי אִם יְסַפֵּר, יַעֲשׂוּ לוֹ עַיִן הָרָע","כִּי אָסוּר לְלַמֵּד אֶת הַמַּסֶּכֶת לְמִי שֶׁשּׁוֹאֵל"],1,"חֲכָמִים הִתִּירוּ לְשַׁנּוֹת בְּעִנְיְנֵי הַמַּסֶּכֶת מִשּׁוּם עֲנָוָה, שֶׁלֹּא יְסַפֵּר בְּעַצְמוֹ עַל יְדִיעוֹתָיו. וְגַם כָּאן עָדִיף לְדַבֵּר בְּלָשׁוֹן שֶׁאֶפְשָׁר לְהָבִין בִּשְׁתֵּי דְּרָכִים, וְלֹא בְּשֶׁקֶר גָּמוּר.","פֶּרֶק ב׳, הֲלָכוֹת ט״ז–י״ז","אֱמֶת וְיֹשֶׁר"],["חָבֵר בָּטוּחַ שֶׁאָבִי לָקַח לוֹ עֵט, וּמְבַקֵּשׁ שֶׁתַּגִּיד לַמּוֹרֶה שֶׁרָאִיתָ. אֲבָל לֹא רָאִיתָ. מָה עוֹשִׂים?",["לֹא אוֹמְרִים, וְגַם לֹא עוֹמְדִים שָׁם כְּאִלּוּ רָאִינוּ","אוֹמְרִים שֶׁרָאִינוּ, כִּי חָבֵר טוֹב בֶּטַח לֹא מְשַׁקֵּר","לֹא מְדַבְּרִים, אֲבָל עוֹמְדִים לְיָדוֹ כְּאִלּוּ יוֹדְעִים","אוֹמְרִים שֶׁכִּמְעַט רָאִינוּ, כְּדֵי לַעֲזֹר לוֹ"],0,"\"מִדְּבַר שֶׁקֶר תִּרְחָק\" – אָסוּר לְהָעִיד עַל מָה שֶׁלֹּא רָאִינוּ, גַּם כְּשֶׁבְּטוּחִים שֶׁהֶחָבֵר צוֹדֵק. וַאֲפִלּוּ לְהֵרָאוֹת כְּמִי שֶׁעוֹמֵד לְשַׁקֵּר – אָסוּר.","פֶּרֶק ב׳, הֲלָכָה ה׳","אֱמֶת וְיֹשֶׁר"],["רַב חָשׁוּב בָּא לִשְׂמֹחַ אֵצֶל שְׁכֵנָיו עִם סִיר אֹכֶל, וְהוּא יוֹדֵעַ שֶׁיֵּשׁ שָׁם אֹכֶל בְּשֶׁפַע. מָה הַדִּין?",["אָסוּר, כִּי זוֹ גְּנֵבַת דַּעַת – אֵין צֹרֶךְ בָּאֹכֶל","מֻתָּר רַק אִם יַשְׁאִיר שָׁם אֶת הָאֹכֶל בְּכָל מִקְרֶה","מֻתָּר, כִּי כָּךְ הוּא מְכַבֵּד אוֹתָם בְּעֵינֵי הָאוֹרְחִים","מֻתָּר רַק אִם יַגִּיד מִיָּד שֶׁהוּא יוֹדֵעַ שֶׁאֵין צֹרֶךְ"],2,"כָּאן הָעִקָּר הוּא הַכָּבוֹד: עַצְם הָרָצוֹן שֶׁל אָדָם חָשׁוּב לַעֲזֹר מְכַבֵּד אֶת הַשְּׁכֵנִים, וְלָכֵן אֵין בָּזֶה גְּנֵבַת דַּעַת – גַּם אִם יַחֲזִיר אֶת הַסִּיר הַבַּיְתָה.","פֶּרֶק ג׳, הֲלָכָה ח׳","אֱמֶת וְיֹשֶׁר"],["נֹעַם סִכֵּם לִמְכֹּר לְאָבִי אֶת הָאוֹפַנַּיִם הַיְשָׁנִים שֶׁלּוֹ בְּמֵאָה שְׁקָלִים. אַחַר כָּךְ בָּא חָבֵר אַחֵר וְהִצִּיעַ מֵאָה וְחַמִּשִּׁים. מָה הַדִּין?",["מוֹכֵר לֶחָבֵר הַשֵּׁנִי, כִּי עוֹד לֹא קִבֵּל כֶּסֶף מֵאָבִי","מוֹכֵר לְאָבִי בְּמֵאָה, כִּי הַסִּכּוּם בְּדִבּוּר מְחַיֵּב אוֹתוֹ","מְבַקֵּשׁ גַּם מֵאָבִי מֵאָה וְחַמִּשִּׁים, וְאִם יְסָרֵב – מוֹכֵר לַשֵּׁנִי","עוֹרֵךְ הַגְרָלָה בֵּין שְׁנֵיהֶם, כְּדֵי שֶׁיִּהְיֶה הֲכִי הוֹגֵן"],1,"הַסִּכּוּם הָיָה רַק בְּדִבּוּר, וּבֵית הַדִּין לֹא יַכְרִיחַ אוֹתוֹ – אֲבָל מִי שֶׁחוֹזֵר בּוֹ נִקְרָא ״מְחֻסַּר אֲמָנָה״. לָכֵן מוֹכְרִים לָרִאשׁוֹן, בַּמְּחִיר שֶׁסִּכְּמוּ.","פֶּרֶק ב׳, הֲלָכָה י״א","אֱמֶת וְיֹשֶׁר"],["בְּסִפּוּר עַל הַטִּיּוּל מַגְזִים אֶלְיָשִׁיב: ״רָאִיתִי נָמֵר וּבָרַחְתִּי מִמֶּנּוּ!״ – כְּדֵי שֶׁיִּתְפַּעֲלוּ מִמֶּנּוּ. ״זֶה לֹא מַזִּיק לְאַף אֶחָד״, הוּא אוֹמֵר. מָה נָכוֹן?",["הוּא צוֹדֵק, כִּי שֶׁקֶר שֶׁלֹּא מַזִּיק לְאַחֵר מֻתָּר","הוּא טוֹעֶה, כִּי הַשַּׁקְרָן מַזִּיק קֹדֶם כֹּל לְעַצְמוֹ","הוּא צוֹדֵק, כָּל עוֹד הַסִּפּוּר מַצְחִיק וּמְשַׂמֵּחַ אֶת כֻּלָּם","הוּא טוֹעֶה רַק אִם מִישֶׁהוּ יְגַלֶּה שֶׁהוּא שִׁקֵּר"],1,"מִי שֶׁמִּתְרַגֵּל לְשַׁקֵּר כְּדֵי לִמְשֹׁךְ תְּשׂוּמַת לֵב – מַזִּיק קֹדֶם כֹּל לְעַצְמוֹ. הוּא מִתְרַגֵּל לְדִמְיוֹן בִּמְקוֹם עֻבְדּוֹת, וּמִתְרַחֵק מִן הָאֱמֶת. חֲכָמִים אָמְרוּ שֶׁהַשַּׁקְרָנִים אֵינָם זוֹכִים לִרְאוֹת פְּנֵי שְׁכִינָה.","פֶּרֶק ב׳, הֲלָכָה ד׳","אֱמֶת וְיֹשֶׁר"],["בְּיוֹם רִאשׁוֹן הִבְטִיחַ הִלֵּל לְהַחֲזִיר לְחָבֵר אֶת הַסֵּפֶר עַד יוֹם שְׁלִישִׁי, וּבֶאֱמֶת הִתְכַּוֵּן. אֲבָל הִתְעַצֵּל, וְלֹא הֶחֱזִיר. מָה הַדִּין?",["לֹא עָשָׂה כְּלוּם רַע, כִּי בִּשְׁעַת הַהַבְטָחָה הִתְכַּוֵּן לְקַיֵּם","נִקְרָא ״מְחֻסַּר אֲמָנָה״, כִּי הִתְרַשֵּׁל וְלֹא עָמַד בְּדִבּוּרוֹ","רַק אִם הֶחָבֵר כָּעַס עָלָיו, יֵשׁ בְּזֶה פְּגָם","אֵין בְּזֶה כְּלוּם, כִּי עַל סֵפֶר אֵין הַבְטָחָה מְחַיֶּבֶת"],1,"גַּם מִי שֶׁהִתְכַּוֵּן לְקַיֵּם אֶת דְּבָרוֹ, וְאַחַר כָּךְ הִתְרַשֵּׁל וְלֹא קִיֵּם – נִקְרָא בִּלְשׁוֹן חֲזַ״ל ״מְחֻסַּר אֲמָנָה״, וְאֵין רוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ. וּמִי שֶׁמַּבְטִיחַ וּבְלִבּוֹ יוֹדֵעַ שֶׁלֹּא יְקַיֵּם – עוֹבֵר עַל ״וְהִין צֶדֶק״.","פֶּרֶק ב׳, הֲלָכָה י׳","אֱמֶת וְיֹשֶׁר"],["אָבִי מוֹכֵר לְחָבֵר מִשְׂחָק יָשָׁן בִּמְחִיר זוֹל וְהוֹגֵן. חָסֵר בַּמִּשְׂחָק חֵלֶק אֶחָד, וְאָבִי לֹא מְסַפֵּר עַל כָּךְ. מָה הַדִּין?",["מֻתָּר, כִּי הַמְּחִיר זוֹל וְהוֹגֵן גַּם בְּלִי הַחֵלֶק","יֵשׁ בָּזֶה גְּנֵבַת דַּעַת, כִּי הוּא מַצִּיג אוֹתוֹ כְּשָׁלֵם","מֻתָּר, כִּי הַקּוֹנֶה הָיָה צָרִיךְ לִבְדֹּק לְבַד לִפְנֵי שֶׁקָּנָה","אָסוּר רַק אִם הַחֵלֶק הֶחָסֵר הוּא הֶחָשׁוּב בְּיוֹתֵר"],1,"מוֹכֵר שֶׁמַּסְתִּיר אֶת הַחֶסְרוֹנוֹת – גּוֹנֵב אֶת דַּעַת הַקּוֹנֶה, אֲפִלּוּ כְּשֶׁהַמְּחִיר מַתְאִים לְמָה שֶׁהוּא מוֹכֵר. כִּי הוּא מַצִּיג אֶת הַמִּשְׂחָק כְּשָׁלֵם, וְהוּא אֵינוֹ כָּזֶה. אָבִי צָרִיךְ לְסַפֵּר עַל הַחֵלֶק הֶחָסֵר.","פֶּרֶק ג׳, הֲלָכָה ג׳","אֱמֶת וְיֹשֶׁר"],["מָה הַהֶבְדֵּל בֵּין תִּיק שֶׁהִתְחַלֵּף בְּאֵירוּעַ לְבֵין מִטְרִיָּה שֶׁהִתְחַלְּפָה בְּיוֹם גֶּשֶׁם?",["אֵין הֶבְדֵּל – בִּשְׁנֵיהֶם מֻתָּר לְהִשְׁתַּמֵּשׁ בְּשֶׁל הֶחָבֵר","בַּתִּיק מֻתָּר לְהִשְׁתַּמֵּשׁ, וּבַמִּטְרִיָּה צָרִיךְ לְהַכְרִיז קֹדֶם","בַּמִּטְרִיָּה נָהֲגוּ לְהִשְׁתַּמֵּשׁ בֵּינְתַיִם, וּבַתִּיק – לֹא","אֵין הֶבְדֵּל – בִּשְׁנֵיהֶם אָסוּר בְּכָל מִקְרֶה לְהִשְׁתַּמֵּשׁ"],2,"בַּתִּיק אָסוּר לְהִשְׁתַּמֵּשׁ – אוּלַי הוּא שֶׁל אָדָם שְׁלִישִׁי. עַל מִטְרִיָּה וּמְעִיל גֶּשֶׁם לֹא מַקְפִּידִים, וּבְלִי שִׁמּוּשׁ שְׁנֵיהֶם יִרָּטְבוּ – לָכֵן נָהֲגוּ לְהָקֵל. וְיֵשׁ מַחְמִירִים גַּם בָּזֶה.","פֶּרֶק ד׳, הֲלָכָה ה׳","לֹא תִּגְנֹבוּ"],["יוֹסִי צָרִיךְ לִכְתֹּב מִלָּה אַחַת. עַל הַשֻּׁלְחָן מֻנָּח עֵט פָּשׁוּט שֶׁל חָבֵר שֶׁיָּצָא. מָתַי מֻתָּר לוֹ לְהִשְׁתַּמֵּשׁ בּוֹ?",["כְּשֶׁאִי אֶפְשָׁר לִשְׁאֹל, וְהֶחָבֵר אֵינוֹ קַפְּדָן","תָּמִיד, כִּי עֵט זוֹל אֵינוֹ שָׁוֶה אֲפִלּוּ פְּרוּטָה","רַק אִם יַשְׁאִיר לְיַד הָעֵט פֶּתֶק וּמַטְבֵּעַ קָטָן","אַף פַּעַם, כִּי אָסוּר לִגְנֹב אֲפִלּוּ פָּחוֹת מִפְּרוּטָה"],0,"בִּדְבָרִים זוֹלִים שֶׁאֲנָשִׁים לֹא מַקְפִּידִים עֲלֵיהֶם מֻתָּר – אִם הַבְּעָלִים לֹא כָּאן וְהוּא אֵינוֹ קַפְּדָן. אִם אֶפְשָׁר לִשְׁאֹל – חוֹבָה לִשְׁאֹל. וּמִדַּת חֲסִידוּת לְהַחְמִיר.","פֶּרֶק ד׳, הֲלָכָה ג׳","לֹא תִּגְנֹבוּ"],["הַכַּדּוּר שֶׁל אָרִי מֻנָּח בֶּחָצֵר, וְאָרִי לֹא בַּבַּיִת. יֵשׁ סִכּוּי קָטָן שֶׁהוּא לֹא יַסְכִּים. מָה הַדִּין?",["מֻתָּר, כִּי חֲבֵרִים טוֹבִים תָּמִיד מַסְכִּימִים לְשַׁתֵּף","מֻתָּר, אִם מַחֲזִירִים אֶת הַכַּדּוּר בְּדִיּוּק לַמָּקוֹם","מֻתָּר, כִּי זֶה רַק לִזְמַן קָצָר וְלֹא לְתָמִיד","אָסוּר, כִּי בְּסָפֵק שֶׁל אִסּוּר תּוֹרָה מַחְמִירִים"],3,"שׁוֹאֵל שֶׁלֹּא מִדַּעַת נֶחְשָׁב גַּנָּב, גַּם לִזְמַן קָצָר. כְּשֶׁיֵּשׁ אֲפִלּוּ אָחוּז אֶחָד שֶׁהֶחָבֵר יִתְרַעֵם – לְכָל הַדֵּעוֹת אָסוּר.","פֶּרֶק ד׳, הֲלָכָה ד׳","לֹא תִּגְנֹבוּ"],["הַכַּד שֶׁל דָּנִי נִשְׁבַּר, וְהַדְּבַשׁ מַתְחִיל לְהִשָּׁפֵךְ. לְיָדוֹ כַּד רֵיק שֶׁל אָדָם אַחֵר, שֶׁאֵינוֹ כָּאן. מָה הַדִּין?",["אָסוּר, כִּי שׁוֹאֵל שֶׁלֹּא מִדַּעַת הוּא תָּמִיד גַּנָּב","מֻתָּר לְהַצִּיל בּוֹ, וְאִם הַכַּד נִזּוֹק – מְשַׁלֵּם","מֻתָּר, וְאַחַר כָּךְ מֻתָּר לוֹ לְהַשְׁאִיר אֶת הַכַּד לְעַצְמוֹ","צָרִיךְ קֹדֶם לְחַפֵּשׂ אֶת הַבְּעָלִים, גַּם אִם הַדְּבַשׁ יִשָּׁפֵךְ"],1,"כָּךְ תִּקֵּן יְהוֹשֻׁעַ בִּן נוּן: בְּנֵזֶק פִּתְאוֹמִי מֻתָּר לְהִשְׁתַּמֵּשׁ בִּכְלִי שֶׁל אַחֵר כְּדֵי לְהַצִּיל, כִּי עַד שֶׁיִּמְצְאוּ אֶת הַבְּעָלִים – הַנֵּזֶק כְּבָר יִקְרֶה. וְעַל נֵזֶק לַכְּלִי מְשַׁלְּמִים.","פֶּרֶק ד׳, הֲלָכָה י״א","לֹא תִּגְנֹבוּ"],["חָבֵר שׁוֹאֵל אֶת עֲצָתְךָ אֵיזֶה מִשְׂחָק לִקְנוֹת. אַתָּה יוֹדֵעַ שֶׁהַמִּשְׂחָק שֶׁהוּא רוֹצֶה מִתְקַלְקֵל מַהֵר. מָה עוֹשִׂים?",["מְשַׁבְּחִים אוֹתוֹ, כִּי לֹא נָעִים לְקַלְקֵל לוֹ אֶת הַשִּׂמְחָה","מַמְלִיצִים עָלָיו, כִּי גַּם אֲנַחְנוּ רוֹצִים לְשַׂחֵק בּוֹ","אוֹמְרִים לוֹ בְּיֹשֶׁר שֶׁהַמִּשְׂחָק הַזֶּה מִתְקַלְקֵל מַהֵר","שׁוֹלְחִים אוֹתוֹ לַחֲנוּת שֶׁל הַדּוֹד, כְּדֵי שֶׁיַּרְוִיחַ"],2,"מִי שֶׁאֵינוֹ מֵבִין בְּדָבָר – כְּעִוֵּר בּוֹ. עֵצָה מַטְעָה הִיא מִכְשׁוֹל לִפְנֵי עִוֵּר, וְאִם לְנוֹתֵן הָעֵצָה יֵשׁ רֶוַח מִזֶּה – זוֹ גַּם אוֹנָאָה.","פֶּרֶק ד׳, הֲלָכָה ט״ו","לֹא תִּגְנֹבוּ"],["קְנִיתֶם מֵחֶנְוָנִי גּוֹי בְּהַקָּפָה, וְהוּא שָׁכַח שֶׁאַתֶּם חַיָּבִים לוֹ. מָה הַדִּין?",["חַיָּבִים לְשַׁלֵּם לוֹ, גַּם אִם הוּא כְּבָר שָׁכַח","פְּטוּרִים, כִּי הוּא שָׁכַח בְּעַצְמוֹ וְלֹא בִּקֵּשׁ","פְּטוּרִים, כִּי מִגּוֹי מֻתָּר לְהִשְׁתַּמֵּשׁ בְּטָעוּת","מְשַׁלְּמִים רַק אִם הוּא יִזָּכֵר וְיִדְרֹשׁ אֶת הַכֶּסֶף"],0,"גַּם מִגּוֹי אָסוּר לִגְנֹב אוֹ לְהַטְעוֹת, אֲפִלּוּ בְּדָבָר קָטָן. חוֹב הוּא חוֹב – וּמְשַׁלְּמִים אוֹתוֹ גַּם כְּשֶׁהַמּוֹכֵר שָׁכַח.","פֶּרֶק ד׳, הֲלָכָה ב׳","לֹא תִּגְנֹבוּ"],["בַּעַל הַגְּמָרָא יוֹשֵׁב בַּסַּפְסָל שֶׁלְּיָדְךָ, וְאַתָּה רוֹצֶה לִלְמֹד בָּהּ שָׁעָה. מָה עוֹשִׂים?",["לוֹמְדִים, כִּי נוֹחַ לְאָדָם שֶׁעוֹשִׂים מִצְוָה בְּשֶׁלּוֹ","לוֹמְדִים, אִם מַחֲזִירִים אֶת הַגְּמָרָא בְּדִיּוּק לַמָּקוֹם","לוֹמְדִים, כִּי לִגְמָרָא אֵין דִּין שֶׁל חֵפֶץ רָגִיל","מְבַקְּשִׁים מִמֶּנּוּ רְשׁוּת, כִּי הוּא נִמְצָא כָּאן"],3,"כְּשֶׁהַבְּעָלִים נִמְצָא – תָּמִיד מְבַקְּשִׁים רְשׁוּת. וּלְלִמּוּד מְמֻשָּׁךְ צָרִיךְ רְשׁוּת גַּם כְּשֶׁהוּא לֹא כָּאן, כִּי הַסֵּפֶר מִתְבַּלֶּה.","פֶּרֶק ד׳, הֲלָכָה ח׳","לֹא תִּגְנֹבוּ"],["בַּחֲנוּת רָאִיתָ אִישׁ גָּדוֹל וּמַפְחִיד גּוֹנֵב, וְאַתָּה חוֹשֵׁשׁ שֶׁיִּפְגַּע בְּךָ. מָה הַדִּין?",["חַיָּבִים לִצְעֹק עָלָיו מִיָּד, גַּם אִם זֶה מְסֻכָּן","אֵין חוֹבָה לְהִתְעָרֵב מִיָּד, אֲבָל מוּכָנִים לְסַפֵּר וּלְהָעִיד","שׁוֹתְקִים לְגַמְרֵי, כִּי זֶה לֹא עִנְיָן שֶׁל יְלָדִים","אָסוּר לְסַפֵּר עָלָיו, כִּי זֶה לָשׁוֹן הָרָע"],1,"מִי שֶׁחוֹשֵׁשׁ לְנַפְשׁוֹ אֵינוֹ חַיָּב לְהִתְעָרֵב מִיָּד, אֲבָל צָרִיךְ לִהְיוֹת מוּכָן לְהִתְלוֹנֵן וּלְהָעִיד אַחַר כָּךְ. וְהַצָּלַת מָמוֹן הֶחָבֵר אֵינָהּ לָשׁוֹן הָרָע.","פֶּרֶק ד׳, הֲלָכָה י״ב","לֹא תִּגְנֹבוּ"],["רוֹנִי לָוָה מֵחֲבֵרוֹ כֶּסֶף כְּדֵי לִקְנוֹת סְפָרִים לְבֵית הַסֵּפֶר. בַּחֲנוּת הוּא רָאָה מִשְׂחָק יָקָר. מָה הַדִּין?",["מֻתָּר לִקְנוֹת, כִּי הַכֶּסֶף כְּבָר שֶׁלּוֹ לְגַמְרֵי","אָסוּר לִקְנוֹת בּוֹ מוֹתָרוֹת בְּלִי רְשׁוּת מְפֹרֶשֶׁת מֵהַמַּלְוֶה","מֻתָּר לִקְנוֹת, אִם הוּא בָּטוּחַ שֶׁיַּחֲזִיר אֶת הַכֹּל בַּזְּמַן","מֻתָּר לִקְנוֹת, וּבִלְבַד שֶׁיְּסַפֵּר לַמַּלְוֶה אַחַר כָּךְ"],1,"גַּם מִי שֶׁבָּטוּחַ שֶׁיַּחֲזִיר – לֹא יִקְנֶה בְּכֶסֶף הַהַלְוָאָה מוֹתָרוֹת בְּלִי רְשׁוּת מְפֹרֶשֶׁת. הַמַּלְוֶה נִכְנַס לְסִכּוּן כְּדֵי לַעֲזֹר בְּצֹרֶךְ אֲמִתִּי, וְלֹא כְּדֵי לְמַמֵּן דְּבָרִים מְיֻתָּרִים.","פֶּרֶק ה׳, הֲלָכָה ז׳","מַלְוִים וְנוֹתְנִים"],["לְאַבָּא יֵשׁ כֶּסֶף לְהַלְוָאָה אַחַת. מְבַקְשִׁים מִמֶּנּוּ: דּוֹד שֶׁגָּר בַּשְּׁכוּנָה וְאֵינוֹ עָנִי, וְעָנִי זָר מֵעִיר אַחֶרֶת. לְמִי יַלְוֶה?",["לַדּוֹד, כִּי הוּא גַּם קָרוֹב וְגַם שָׁכֵן","לֶעָנִי, כִּי מִי שֶׁצָּרִיךְ יוֹתֵר קוֹדֵם לַכֹּל","לַדּוֹד, כִּי קְרוֹבֵי מִשְׁפָּחָה תָּמִיד קוֹדְמִים לַכֹּל","יְחַלֵּק אֶת הַכֶּסֶף שָׁוֶה בְּשָׁוֶה בֵּין שְׁנֵיהֶם"],1,"הַכְּלָל הָרִאשׁוֹן – מִי שֶׁצָּרִיךְ יוֹתֵר – גּוֹבֵר עַל קִרְבַת מִשְׁפָּחָה וְעַל קִרְבַת מָקוֹם. מַלְוִים קֹדֶם לֶעָנִי, וְאִם יִשָּׁאֵר כֶּסֶף – לַדּוֹד.","פֶּרֶק ה׳, הֲלָכָה י״ג","מַלְוִים וְנוֹתְנִים"],["שְׁמוּאֵל מוֹכֵר אֶת הָאוֹפַנַּיִם הַיְּשָׁנִים שֶׁלּוֹ. קוֹנֶה יְהוּדִי וְקוֹנֶה גּוֹי רוֹצִים אוֹתָם, וְהַגּוֹי מַצִּיעַ קְצָת יוֹתֵר. מָה עָדִיף?",["לִמְכֹּר לַגּוֹי, כִּי בִּמְכִירָה הַמְּחִיר הוּא הָעִקָּר","לִמְכֹּר לַיְּהוּדִי, אַף שֶׁהַגּוֹי מַצִּיעַ מְחִיר גָּבוֹהַּ יוֹתֵר","לַעֲשׂוֹת הַגְרָלָה בֵּינֵיהֶם, כְּדֵי שֶׁיִּהְיֶה הוֹגֵן לִשְׁנֵיהֶם","לִמְכֹּר לְמִי שֶׁהִגִּיעַ רִאשׁוֹן לִרְאוֹת אֶת הָאוֹפַנַּיִם"],1,"\"וְכִי תִמְכְּרוּ מִמְכָּר לַעֲמִיתֶךָ\" – חֲכָמִים לָמְדוּ שֶׁבִּמְכִירָה וּבִקְנִיָּה מַקְדִּימִים אֶת הַיְּהוּדִי, גַּם כְּשֶׁהַגּוֹי מַצִּיעַ יוֹתֵר.","פֶּרֶק ה׳, הֲלָכָה י״ב","מַלְוִים וְנוֹתְנִים"],["אַבָּא נָתַן לְאֵלִי עֶשְׂרִים שְׁקָלִים לִנְסִיעוֹת, וְנִשְׁאֲרוּ לוֹ חֲמִשָּׁה. אַבָּא אָמַר: \"הָעֹדֶף שֶׁלְּךָ\". מִמָּה מְעַשְּׂרִים?",["מִכָּל עֶשְׂרִים הַשְּׁקָלִים, כִּי כֻּלָּם הִגִּיעוּ לְיָדָיו","רַק מֵחֲמֵשֶׁת הַשְּׁקָלִים שֶׁל הָעֹדֶף שֶׁנִּשְׁאֲרוּ אֶצְלוֹ","מִשּׁוּם דָּבָר, כִּי אַבָּא כְּבָר עִשֵּׂר אֶת הַכֶּסֶף","מִשּׁוּם דָּבָר, כִּי יְלָדִים אֵינָם מְעַשְּׂרִים דְּמֵי כִּיס"],1,"כֶּסֶף שֶׁנִּתַּן לִנְסִיעוֹת אֵינוֹ לְשִׁמּוּשׁ חָפְשִׁי, וְאֵין מְעַשְּׂרִים אוֹתוֹ. אֲבָל הָעֹדֶף – שֶׁאַבָּא הִרְשָׁה לְהִשְׁתַּמֵּשׁ בּוֹ כִּרְצוֹנוֹ – חַיָּב בְּמַעֲשֵׂר, גַּם אִם אַבָּא כְּבָר עִשֵּׂר.","פֶּרֶק ו׳, הֲלָכָה ט׳","מַלְוִים וְנוֹתְנִים"],["דָּוִד חַיָּב לַחֲבֵרוֹ כֶּסֶף, וְגַם הִגִּיעַ הַזְּמַן לָתֵת מַעֲשֵׂר. אֵין לוֹ מַסְפִּיק לִשְׁנֵיהֶם. מָה יַעֲשֶׂה?",["יְשַׁלֵּם אֶת הַחוֹב, וְיִרְשֹׁם כַּמָּה הוּא חַיָּב לַמַּעֲשֵׂר","יִתֵּן קֹדֶם אֶת הַמַּעֲשֵׂר, כִּי מִצְוָה קוֹדֶמֶת לְכָל חוֹב","יִלְוֶה כֶּסֶף מֵחָבֵר אַחֵר כְּדֵי לָתֵת אֶת הַמַּעֲשֵׂר","יְחַלֵּק חֲצִי לֶחָבֵר וַחֲצִי לַצְּדָקָה, וְיִהְיֶה פָּטוּר"],0,"מִי שֶׁחַיָּב לַחֲבֵרוֹ – מְשַׁלֵּם קֹדֶם אֶת הַחוֹב, וְדוֹחֶה אֶת הַמַּעֲשֵׂר. הוּא רוֹשֵׁם בְּפִנְקָס כַּמָּה הוּא חַיָּב, וּמְשַׁלֵּם הַכֹּל כְּשֶׁיּוּכַל. לֹא לוֹוִים כְּדֵי לָתֵת מַעֲשֵׂר.","פֶּרֶק ו׳, הֲלָכָה י״ב","מַלְוִים וְנוֹתְנִים"],["לִקְרַאת בַּר הַמִּצְוָה רוֹצֶה נֹעַם לִקְנוֹת לְעַצְמוֹ תְּפִלִּין בְּכֶסֶף הַמַּעֲשֵׂר שֶׁחָסַךְ. מָה הַדִּין?",["מֻתָּר, כִּי תְּפִלִּין הֵן מִצְוָה חֲשׁוּבָה מְאוֹד שֶׁל כָּל יְהוּדִי","אָסוּר לִקְנוֹת לְעַצְמוֹ, אֲבָל מֻתָּר לִקְנוֹת תְּפִלִּין לְעָנִי","מֻתָּר, אִם יַשְׁאִיל אוֹתָן לִפְעָמִים גַּם לַאֲחֵרִים","מֻתָּר, אִם יִקְנֶה תְּפִלִּין זוֹלוֹת וּפְשׁוּטוֹת בְּיוֹתֵר"],1,"אָסוּר לְשַׁלֵּם מִכֶּסֶף הַמַּעֲשֵׂר מִצְוָה שֶׁאָדָם חַיָּב בָּהּ בְּעַצְמוֹ, כְּמוֹ תְּפִלִּין לְעַצְמוֹ. אֲבָל לִקְנוֹת תְּפִלִּין לְאָדָם עָנִי – מֻתָּר.","פֶּרֶק ו׳, הֲלָכָה י״א","מַלְוִים וְנוֹתְנִים"],["אַבָּא שֶׁל אָבִיחַי הִלְוָה פַּעֲמַיִם, וְלֹא הֶחֱזִירוּ לוֹ. עַכְשָׁו הוּא אוֹמֵר: \"לֹא אַלְוֶה יוֹתֵר לְאַף אֶחָד\". מָה נָכוֹן?",["צָדַק, כִּי מִי שֶׁהִפְסִיד פַּעַם פָּטוּר מִן הַמִּצְוָה","לֹא נָכוֹן; רַק לְמִי שֶׁיָּדוּעַ כְּלֹא נֶאֱמָן לֹא מַלְוִים","צָדַק, כִּי מֵעַכְשָׁו יִתֵּן רַק צְדָקָה וְלֹא הַלְוָאוֹת","לֹא נָכוֹן; צָרִיךְ לְהַלְווֹת גַּם לְמִי שֶׁלֹּא הֶחֱזִיר מֵעוֹלָם"],1,"בַּעַל חֲנוּת לֹא סוֹגֵר אֶת הַחֲנוּת בִּגְלַל כַּמָּה קוֹנִים שֶׁלֹּא שִׁלְּמוּ. רֹב הָאֲנָשִׁים נֶאֱמָנִים, וְרַק לְמִי שֶׁיָּדוּעַ שֶׁאֵינוֹ מַחֲזִיר – לֹא מַלְוִים, וְעוֹזְרִים לוֹ בִּצְדָקָה.","פֶּרֶק ה׳, הֲלָכוֹת ח׳–ט׳","מַלְוִים וְנוֹתְנִים"],["לְיַעֲקֹב יֵשׁ אֶלֶף שְׁקָלִים לְהַלְוָאוֹת. עֲשָׂרָה מְבַקְשִׁים מֵאָה שְׁקָלִים כָּל אֶחָד, וְאֶחָד מְבַקֵּשׁ אֶת כָּל הָאֶלֶף. מָה עָדִיף בְּדֶרֶךְ כְּלָל?",["לְהַלְווֹת לַעֲשָׂרָה, כִּי בְּכָל הַלְוָאָה יֵשׁ עוֹד מִצְוָה","לְהַלְווֹת לָאֶחָד, כִּי הַלְוָאָה גְּדוֹלָה הִיא מִצְוָה גְּדוֹלָה יוֹתֵר","לְהַלְווֹת לְמִי שֶׁהִתְקַשֵּׁר רִאשׁוֹן וּבִקֵּשׁ אֶת הַהַלְוָאָה","לֹא לְהַלְווֹת כְּלָל, כְּדֵי שֶׁאַף אֶחָד לֹא יִפָּגַע"],0,"בְּדֶרֶךְ כְּלָל עָדִיף לְהַלְווֹת לְהַרְבֵּה אֲנָשִׁים, כִּי בְּכָל הַלְוָאָה מְקַיְּמִים מִצְוָה – \"הַכֹּל לְפִי רֹב הַמַּעֲשֶׂה\". אֲבָל אִם הָאֶחָד עָלוּל לְהִתְמוֹטֵט בְּלִי הַהַלְוָאָה הַגְּדוֹלָה – הוּא קוֹדֵם.","פֶּרֶק ה׳, הֲלָכָה י׳","מַלְוִים וְנוֹתְנִים"],["לִכְבוֹד בַּר הַמִּצְוָה קִבֵּל יַעֲקֹב הַרְבֵּה מַתְּנוֹת כֶּסֶף. הוּא רוֹצֶה לְהַפְרִישׁ מֵהֶן מַעֲשֵׂר כַּהֲלָכָה. מָה עָדִיף?",["לְחַשֵּׁב בְּעֵרֶךְ, וְלָתֵת סְכוּם עָגֹל שֶׁנִּרְאֶה לוֹ מַתְאִים","לִרְשֹׁם כָּל מַתָּנָה בְּמַחְבֶּרֶת, וּלְחַשֵּׁב אֶת הַמַּעֲשֵׂר בְּדִיּוּק","לְהַפְרִישׁ רַק מִן הַמַּתָּנוֹת הַגְּדוֹלוֹת, וּלְוַתֵּר עַל הַקְּטַנּוֹת","לְחַכּוֹת עִם הַמַּעֲשֵׂר עַד שֶׁיַּתְחִיל לַעֲבֹד וּלְהַרְוִיחַ"],1,"עָדִיף לְחַשֵּׁב אֶת מַעְשַׂר הַכְּסָפִים בְּדִיּוּק, וּלְשֵׁם כָּךְ לְהַקְדִּישׁ מַחְבֶּרֶת אוֹ פִּנְקָס. יֵשׁ אוֹמְרִים שֶׁהַסְּגֻלָּה לַעֲשִׁירוּת הִיא דַּוְקָא כְּשֶׁמְּחַשְּׁבִים בְּדִיּוּק. וְאִם יִרְצֶה – יוֹסִיף אַחַר כָּךְ.","פֶּרֶק ו׳, הֲלָכָה י׳","מַלְוִים וְנוֹתְנִים"],["בְּאֵיזֶה אֵרוּחַ מְקַיְּמִים אֶת הַמִּצְוָה שֶׁגְּדוֹלָה מִקַּבָּלַת פְּנֵי הַשְּׁכִינָה?",["כְּשֶׁמְּאָרְחִים אֶת הַשְּׁכֵנִים לִסְעֻדַּת שַׁבָּת מְהֻדֶּרֶת","כְּשֶׁמְּאָרְחִים מִי שֶׁאֵין לוֹ מָקוֹם לֶאֱכֹל וְלִישֹׁן","כְּשֶׁמְּאָרְחִים קְרוֹבִים עֲשִׁירִים שֶׁבָּאוּ לְטַיֵּל בָּעִיר","כְּשֶׁמַּזְמִינִים הַרְבֵּה אֲנָשִׁים וּמַגִּישִׁים לָהֶם מִכָּל טוּב"],1,"הַמַּעֲלָה הַגְּדוֹלָה נֶאֶמְרָה עַל אֵרוּחַ מִי שֶׁאֵין לוֹ אֵיפֹה לֶאֱכֹל וְלִישֹׁן. אֵרוּחַ שְׁכֵנִים אוֹ קְרוֹבִים שֶׁיְּכוֹלִים לָלוּן בְּמָלוֹן – חָשׁוּב, אֲבָל אֵינוֹ בַּדַּרְגָּה הַזּוֹ.","פֶּרֶק ז׳, הֲלָכָה ד׳","אוֹרְחִים וַחֲבֵרִים"],["הַיּוֹם כִּמְעַט אֵין אֲנָשִׁים רְעֵבִים. אֵיךְ מְקַיְּמִים הַיּוֹם אֶת הַכְנָסַת הָאוֹרְחִים בְּהִדּוּר?",["הַמִּצְוָה כְּבָר אֵינָהּ שַׁיֶּכֶת בַּזְּמַן הַזֶּה כְּלָל","מְאָרְחִים בְּחֹם מִי שֶׁבּוֹדֵד, עָצוּב אוֹ רָחוֹק מִבֵּיתוֹ","מְאָרְחִים רַק מִי שֶׁבֶּאֱמֶת אֵין לוֹ מַה לֶּאֱכֹל","שׁוֹלְחִים כֶּסֶף לְמִסְעָדָה, וְהָאוֹרֵחַ אוֹכֵל שָׁם לְבַד"],1,"הַמִּצְוָה נִשְׁאֲרָה, אֲבָל הַדָּגֵשׁ הִשְׁתַּנָּה: הָעֹנִי הַקָּשֶׁה הַיּוֹם הוּא בְּדִידוּת וְעֶצֶב. מִי שֶׁמְּאָרֵחַ בְּחֹם בָּחוּר רָחוֹק מִבֵּיתוֹ אוֹ אָדָם בּוֹדֵד – מְקַיֵּם אֶת הַמִּצְוָה בְּכָל הִדּוּרָהּ.","פֶּרֶק ז׳, הֲלָכָה ו׳","אוֹרְחִים וַחֲבֵרִים"],["אֲבִיגְדוֹר אוֹמֵר לְחָבֵר: \"בּוֹא אֵלֵינוּ לְשַׁבָּת!\" – אֲבָל בְּלִבּוֹ הוּא מְקַוֶּה שֶׁהֶחָבֵר יְסָרֵב. מָה הַדִּין?",["זֶה נִימוּס יָפֶה, כִּי כָּךְ נוֹהֲגִים רֹב הָאֲנָשִׁים","אָסוּר, כִּי זֶה \"אֶחָד בַּפֶּה וְאֶחָד בַּלֵּב\"","מֻתָּר, אִם הוּא בָּטוּחַ שֶׁהֶחָבֵר בֶּאֱמֶת לֹא יָבוֹא","מֻתָּר, וְאִם יָבוֹא יַסְבִּירוּ לוֹ שֶׁזֶּה זְמַן לֹא מַתְאִים"],1,"הַזְמָנָה שֶׁאֵינָהּ מִן הַלֵּב הִיא גְּנֵבַת דַּעַת. אוֹ שֶׁלֹּא מַזְמִינִים, אוֹ – וְזֶה עָדִיף – רוֹצִים בֶּאֱמֶת וּמַזְמִינִים בְּלֵב שָׁלֵם.","פֶּרֶק ז׳, הֲלָכָה י׳","אוֹרְחִים וַחֲבֵרִים"],["מָה פֵּרוּשׁ הַפָּסוּק \"הֹקַר רַגְלְךָ מִבֵּית רֵעֶךָ\"?",["בַּקֵּר אֶצְלוֹ לִפְעָמִים, כְּדֵי שֶׁכָּל בִּקּוּר יִהְיֶה יָקָר","אַל תִּכָּנֵס לְבֵית חָבֵר בְּלִי לְהָסִיר אֶת הַנַּעֲלַיִם","לְעוֹלָם אַל תִּתְאָרֵחַ אֵצֶל חֲבֵרִים, אֶלָּא רַק בְּבֵית מָלוֹן","בַּקֵּר אֶת רֵעֲךָ בְּכָל יוֹם, כְּדֵי שֶׁיִּשְׂמַח בְּךָ"],0,"\"הֹקַר\" – עֲשֵׂה אֶת רַגְלְךָ יְקָרָה. מִי שֶׁמְּבַקֵּר מִדַּי, עָלוּל לְהִמָּאֵס עַל חֲבֵרוֹ. מֻתָּר לְהִתְאָרֵחַ – אֲבָל בְּלִי לְהַכְבִּיד.","פֶּרֶק ז׳, הֲלָכָה ט׳","אוֹרְחִים וַחֲבֵרִים"],["לָמָּה שָׁכַח רַבִּי אֶלְעָזָר בֶּן עֲרָךְ אֶת תַּלְמוּדוֹ?",["כִּי עָבַר לְמָקוֹם שֶׁל תַּעֲנוּגוֹת, רָחוֹק מֵחֲבֵרָיו הַלּוֹמְדִים","כִּי הָיָה עָסוּק מְאוֹד בְּפַרְנָסָה וְלֹא הָיָה לוֹ זְמַן","כִּי חֲבֵרָיו עָבְרוּ לָגוּר אִתּוֹ וְהִפְרִיעוּ לוֹ לִלְמֹד","כִּי הִתְחִיל לְלַמֵּד יְלָדִים, וְלֹא חָזַר עַל לִמּוּדוֹ"],0,"הוּא חָשַׁב שֶׁחֲבֵרָיו יָבוֹאוּ אַחֲרָיו, וְהֵם לֹא בָּאוּ. בְּלִי חֶבְרָה לוֹמֶדֶת נֶעֱקַר תַּלְמוּדוֹ – וּמִכָּאן: \"הֱוֵי גוֹלֶה לִמְקוֹם תּוֹרָה, וְאַל תֹּאמַר שֶׁהִיא תָּבוֹא אַחֲרֶיךָ\".","פֶּרֶק י״ז, הֲלָכָה ג׳","אוֹרְחִים וַחֲבֵרִים"],["מָתַי נָכוֹן לָגוּר בֵּין רְחוֹקִים מִתּוֹרָה כְּדֵי לְקָרֵב אוֹתָם?",["רַק אִם הוּא מַכִּיר שָׁם קְרוֹבֵי מִשְׁפָּחָה רַבִּים","תָּמִיד, כִּי מִי שֶׁעוֹסֵק בְּמִצְוָה לֹא יִנָּזֵק לְעוֹלָם","כְּשֶׁרוֹצִים לִשְׁמֹעַ מִמֶּנּוּ, וְהוּא לֹא יֻשְׁפַּע מֵהֶם לְרָעָה","רַק אִם יִתְנַהֵג בְּדִיּוּק כְּמוֹתָם, כְּדֵי שֶׁיֶּאֶהְבוּ אוֹתוֹ"],2,"שְׁנֵי תְּנָאִים: שֶׁיֵּשׁ שָׁם מִי שֶׁרוֹצֶה לִשְׁמֹעַ תּוֹרָה, וְשֶׁהַשָּׁלִיחַ חָזָק וְלֹא יֻשְׁפַּע. וּלְקָרֵב חָבֵר מִדֵּי פַּעַם – כָּל אֶחָד יָכוֹל.","פֶּרֶק י״ז, הֲלָכוֹת ו׳–ז׳","אוֹרְחִים וַחֲבֵרִים"],["בַּשְּׁכוּנָה שֶׁל אִיתָי גָּר יֶלֶד מִמִּשְׁפָּחָה שֶׁאֵינָהּ שׁוֹמֶרֶת מִצְווֹת. אֵיךְ נָכוֹן לְהִתְיַחֵס אֵלָיו?",["מִתְרַחֲקִים מִמֶּנּוּ לְגַמְרֵי, וְלֹא מְדַבְּרִים אִתּוֹ בִּכְלָל","אוֹהֲבִים אוֹתוֹ וּמְכַבְּדִים, וְלֹא נִפְרָדִים מִמֶּנּוּ בְּשִׂנְאָה","מְחַקִּים אֶת כָּל מִנְהָגָיו, כְּדֵי שֶׁיַּרְגִּישׁ שֶׁהוּא שַׁיָּךְ","מוֹכִיחִים אוֹתוֹ בְּקוֹל רָם בְּכָל פַּעַם שֶׁהוּא טוֹעֶה"],1,"כָּל יְהוּדִי הוּא בְּנוֹ שֶׁל ה׳, וְאָסוּר לְהִפָּרֵד מִמֶּנּוּ בְּשִׂנְאָה. מַכִּירִים וְאוֹהֲבִים – וְאֶת הַחֲבֵרִים הַקְּרוֹבִים בּוֹחֲרִים מֵחֶבְרָה שֶׁמְּחַזֶּקֶת אוֹתָנוּ.","פֶּרֶק י״ז, הֲלָכוֹת ד׳, ח׳","אוֹרְחִים וַחֲבֵרִים"],["מִשְׁפַּחַת לֵוִי מְתַכְנֶנֶת סְעֻדַּת חַג. מָה יַהֲפֹךְ אֶת הַשִּׂמְחָה שֶׁלָּהֶם לְשִׂמְחַת מִצְוָה?",["לְהַזְמִין אֶת מִשְׁפַּחַת הָעוֹלִים הַחֲדָשָׁה וְאֶת הַשָּׁכֵן הַבּוֹדֵד","לֶאֱכֹל רַק בְּיַחַד עִם בְּנֵי הַמִּשְׁפָּחָה הַקְּרוֹבָה","לְהַגִּישׁ הַרְבֵּה מַאֲכָלִים יְקָרִים וּמְיֻחָדִים לְכָל הַמִּשְׁפָּחָה","לְהַזְמִין רַק אֶת הַחֲבֵרִים שֶׁהִזְמִינוּ אוֹתָם בַּשָּׁנָה שֶׁעָבְרָה"],0,"שִׂמְחָה שֶׁל מִשְׁפָּחָה בִּלְבַד, בְּלִי לְשַׂמֵּחַ בּוֹדְדִים וַעֲנִיִּים, הִיא \"שִׂמְחַת כְּרֵסוֹ\". וְלַעֲזֹר לָעוֹלִים הַחֲדָשִׁים – זוֹ מִצְוָה שֶׁל כָּל הָעָם.","פֶּרֶק ז׳, הֲלָכוֹת ז׳, י״ב","אוֹרְחִים וַחֲבֵרִים"],["עוֹדֵד אוֹמֵר: \"ה׳ שׁוֹמֵר עָלַי, אָז אֲנִי לֹא צָרִיךְ קַסְדָּה כְּשֶׁאֲנִי רוֹכֵב עַל אוֹפַנַּיִם\". מָה נָכוֹן?",["צוֹדֵק, כִּי מִי שֶׁמַּאֲמִין בֶּאֱמֶת לֹא צָרִיךְ לְהִזָּהֵר","טוֹעֶה; עוֹשִׂים כָּל מָה שֶׁהַשֵּׂכֶל דּוֹרֵשׁ, וּמִתְפַּלְּלִים לַה׳","צוֹדֵק, אֲבָל רַק אִם הוּא אוֹמֵר קֹדֶם תְּפִלַּת הַדֶּרֶךְ","טוֹעֶה, כִּי אֵין קֶשֶׁר בֵּין אֱמוּנָה לְבֵין הַחַיִּים"],1,"הָאֱמוּנָה אֵינָהּ אוֹמֶרֶת \"אַל תַּעֲשֶׂה כְּלוּם\". ה׳ מַנְהִיג אֶת הָעוֹלָם בְּדֶרֶךְ הַטֶּבַע, וְלָכֵן נִזְהָרִים כְּמוֹ שֶׁהַשֵּׂכֶל דּוֹרֵשׁ – וְיוֹדְעִים שֶׁגַּם אָז צְרִיכִים לְעֶזְרָתוֹ.","פֶּרֶק ט׳, הֲלָכָה י״ד; פֶּרֶק י׳, הֲלָכָה א׳","שׁוֹמְרִים עַל הַחַיִּים"],["הַכִּתָּה מְתַכְנֶנֶת טִיּוּל בְּנַחַל. מִי קוֹבֵעַ אִם הַמַּסְלוּל מְסֻכָּן מִדַּי?",["הַתַּלְמִידִים, לְפִי מָה שֶׁנִּרְאֶה לָהֶם מְעַנְיֵן יוֹתֵר","אֲנָשִׁים בַּעֲלֵי נִסָּיוֹן, כְּמוֹ הָאַחְרָאִים בִּיחִידוֹת הַחִלּוּץ","מִי שֶׁכְּבָר הָלַךְ בַּמַּסְלוּל פַּעַם אַחַת וְלֹא נִפְגַּע","אִישׁ לֹא קוֹבֵעַ, כִּי בְּטִיּוּל שֶׁל מִצְוָה אֵין סַכָּנָה"],1,"דֶּרֶךְ מְסֻכֶּנֶת אָסוּר לְטַיֵּל בָּהּ, וּבְדֶרֶךְ שֶׁיֵּשׁ בָּהּ קְצָת סַכָּנָה רָאוּי לֹא לְטַיֵּל לְשֵׁם הֲנָאָה. אֶת זֶה קוֹבְעִים בַּעֲלֵי נִסָּיוֹן – אַנְשֵׁי הַמִּשְׁטָרָה וְהַחִלּוּץ.","פֶּרֶק ט׳, הֲלָכָה ז׳","שׁוֹמְרִים עַל הַחַיִּים"],["בַּתַּחֲנָה, אִישׁ מְעַשֵּׁן לְיַד אַבָּא שֶׁל שָׁלוֹם. הַמְּעַשֵּׁן אוֹמֵר: \"אֲנִי מְעַשֵּׁן כָּאן כְּבָר שָׁנִים\". מָה הַדִּין?",["הוּא צוֹדֵק, כִּי מִי שֶׁהִתְרַגֵּל לְמָקוֹם קָנָה בּוֹ זְכוּת","אַבָּא רַשַּׁאי לְבַקֵּשׁ שֶׁיַּפְסִיק, כִּי עָשָׁן מַזִּיק לַאֲחֵרִים","אַבָּא צָרִיךְ לְהִתְרַחֵק, כִּי אָסוּר לְהָעִיר לְאָדָם מְבֻגָּר","מֻתָּר לוֹ לְעַשֵּׁן, כִּי זֶה מָקוֹם פָּתוּחַ לְכֻלָּם"],1,"בְּמָקוֹם צִבּוּרִי אֶפְשָׁר לִדְרֹשׁ מִן הַמְּעַשֵּׁן לְהַפְסִיק. אֵין לְאָדָם \"זְכוּת\" לְהַזִּיק לִשְׁכֵנָיו, גַּם אִם עָשָׂה זֹאת שָׁנִים – וְהַיּוֹם יָדוּעַ שֶׁהָעָשָׁן מַזִּיק גַּם לְמִי שֶׁעוֹמֵד לְיָדוֹ.","פֶּרֶק ט׳, הֲלָכָה י׳","שׁוֹמְרִים עַל הַחַיִּים"],["אַבָּא מְבַקֵּשׁ מִנְּתַנְאֵל לִקְנוֹת לוֹ סִיגַרְיוֹת. מָה כּוֹתֵב הָרַב מֶלָמֵד?",["חוֹבָה לִקְנוֹת תָּמִיד, כִּי כִּבּוּד אָב דּוֹחֶה הַכֹּל","בְּעִקָּרוֹ אָסוּר, אֲבָל אִם יִגְרֹם מְרִיבָה גְּדוֹלָה עָדִיף לִקְנוֹת","אָסוּר תָּמִיד, גַּם אִם הַבַּיִת כֻּלּוֹ יִתְמַלֵּא בִּמְרִיבוֹת","מֻתָּר לִקְנוֹת, כִּי בְּלִי הַבֵּן הָאָב לֹא יַשִּׂיג אוֹתָן"],1,"כִּבּוּד הוֹרִים אֵינוֹ דּוֹחֶה מִצְווֹת, וְלָכֵן בְּעִקָּרוֹ אָסוּר לַעֲזֹר לְעִשּׁוּן. אֲבָל אִם הַסֵּרוּב יִפְגַּע קָשֶׁה בָּאַהֲבָה וּבַכָּבוֹד שֶׁבֵּין הַבֵּן לְאָבִיו – עָדִיף לִקְנוֹת.","פֶּרֶק ט׳, הֲלָכָה י״א","שׁוֹמְרִים עַל הַחַיִּים"],["בַּנְּסִיעָה בָּאוֹטוֹבּוּס הַנֶּהָג נוֹסֵעַ מַהֵר מְאוֹד, וְאַבָּא שֶׁל אֶלְחָנָן רוֹצֶה לְהָעִיר לוֹ. אֵיךְ נָכוֹן?",["לִצְעֹק עָלָיו מוּל כָּל הַנּוֹסְעִים, כְּדֵי שֶׁיִּתְבַּיֵּשׁ","לֹא לְהָעִיר, כִּי מִמֵּילָא הַנֶּהָג לֹא יִשְׁמַע לוֹ","לָגֶשֶׁת אֵלָיו בְּשֶׁקֶט, וּלְהָעִיר לוֹ בְּכָבוֹד וּבְאַהֲבָה","לְחַכּוֹת עַד שֶׁיֵּרְדוּ, וְאָז לְסַפֵּר לְכֻלָּם עָלָיו"],2,"מִצְוָה לְהָעִיר, גַּם כְּשֶׁהַסִּכּוּי קָטָן. וּמוֹכִיחִים בְּצִנְעָה וּמִתּוֹךְ אַהֲבָה – \"וְלֹא תִשָּׂא עָלָיו חֵטְא\", כְּדֵי שֶׁלֹּא יֵעָלֵב.","פֶּרֶק י׳, הֲלָכָה ג׳","שׁוֹמְרִים עַל הַחַיִּים"],["מִשְׁפַּחַת אַבְרָהָמִי יוֹצֵאת בַּבֹּקֶר לִירוּשָׁלַיִם, וּמְתַכְנֶנֶת לִנְסֹעַ מִשָּׁם בְּאוֹתוֹ יוֹם לְסַבָּא בְּעִיר אַחֶרֶת. כַּמָּה פְּעָמִים יֹאמְרוּ תְּפִלַּת הַדֶּרֶךְ?",["פַּעַם אַחַת בַּבֹּקֶר, וּמְכַוְּנִים עַל כָּל הַנְּסִיעוֹת שֶׁל הַיּוֹם","בְּכָל יְצִיאָה מֵעִיר, כִּי כָּל נְסִיעָה הִיא דֶּרֶךְ חֲדָשָׁה","רַק בַּנְּסִיעָה הָאֲרֻכָּה בְּיוֹתֵר, וְלֹא בַּנְּסִיעוֹת הַקְּצָרוֹת","בִּכְלָל לֹא, כִּי בִּמְכוֹנִית מְהִירָה הַדֶּרֶךְ קְצָרָה"],0,"מִי שֶׁתִּכְנֵן מֵרֹאשׁ כַּמָּה נְסִיעוֹת בְּאוֹתוֹ יוֹם – אוֹמֵר פַּעַם אַחַת וּמְכַוֵּן עַל כֻּלָּן. וּמוֹדְדִים לְפִי אֹרֶךְ הַדֶּרֶךְ, וְלֹא לְפִי מְהִירוּת הַמְּכוֹנִית.","פֶּרֶק י׳, הֲלָכוֹת ח׳–ט׳","שׁוֹמְרִים עַל הַחַיִּים"],["הַדֶּרֶךְ לַיִּשּׁוּב שֶׁל סַבָּא אֲרֻכָּה רַק שְׁנֵי קִילוֹמֶטְרִים, אֲבָל הִיא יְדוּעָה כִּמְסֻכֶּנֶת. מָה הַדִּין?",["אוֹמְרִים, כִּי זוֹ דֶּרֶךְ שֶׁמֻּחְזֶקֶת כִּמְסֻכֶּנֶת","לֹא אוֹמְרִים, כִּי הַדֶּרֶךְ קְצָרָה מִפַּרְסָה","אוֹמְרִים רַק אִם הַנְּסִיעָה נִמְשֶׁכֶת יוֹתֵר מִשָּׁעָה","אוֹמְרִים, אֲבָל רַק בַּחֲזָרָה הַבַּיְתָה בָּעֶרֶב"],0,"בְּדֶרֶךְ רְגִילָה אוֹמְרִים רַק עַל יוֹתֵר מִפַּרְסָה. אֲבָל דֶּרֶךְ שֶׁיְּדוּעָה כִּמְסֻכֶּנֶת – אוֹמְרִים עָלֶיהָ תְּפִלַּת הַדֶּרֶךְ גַּם כְּשֶׁהִיא קְצָרָה.","פֶּרֶק י׳, הֲלָכָה י׳","שׁוֹמְרִים עַל הַחַיִּים"],["בְּשַׁבָּת, סַבָּא מַרְגִּישׁ פִּתְאוֹם כְּאֵב חָזָק בֶּחָזֶה, וְלֹא בָּרוּר אִם זֶה מְסֻכָּן. מָה עוֹשִׂים?",["קֹדֶם הוֹלְכִים לִשְׁאֹל אֶת הָרַב אִם מֻתָּר לְהִתְקַשֵּׁר","מְחַכִּים לְמוֹצָאֵי שַׁבָּת, כִּי לֹא בָּטוּחַ שֶׁזֶּה מְסֻכָּן","מִזְדָּרְזִים לְהַזְמִין עֶזְרָה מִיָּד, גַּם כְּשֶׁיֵּשׁ רַק סָפֵק","מְבַקְשִׁים מִיֶּלֶד קָטָן לְהִתְקַשֵּׁר, כְּדֵי לְהָקֵל בַּחִלּוּל"],2,"גַּם סָפֵק פִּקּוּחַ נֶפֶשׁ דּוֹחֶה שַׁבָּת, וּמִזְדָּרְזִים. מִי שֶׁעוֹצֵר לִשְׁאֹל – כְּשׁוֹפֵךְ דָּמִים. וְלֹא מַעֲדִיפִים קְטַנִּים: דַּוְקָא הַגָּדוֹל שֶׁבַּמָּקוֹם מְחַלֵּל, כְּדֵי שֶׁכֻּלָּם יָבִינוּ שֶׁזּוֹ הַהֲלָכָה.","פֶּרֶק י״א, הֲלָכָה י׳","שׁוֹמְרִים עַל הַחַיִּים"],["בַּטִּיּוּל הַשְּׁנָתִי הֵבִיא יֶלֶד מִן הַשִּׁכְבָה סִיגַרְיָה, וְהוּא מְשַׁכְנֵעַ אֶת כֻּלָּם: ״רַק לְנַסּוֹת פַּעַם אַחַת!״ מָה נָכוֹן לְפִי הַתּוֹרָה?",["מֻתָּר לוֹ לְהַצִּיעַ, כִּי כָּל אֶחָד מַחְלִיט לְבַד","אָסוּר לוֹ, כִּי הוּא מַכְשִׁיל אוֹתָם בְּ״לִפְנֵי עִוֵּר״","מֻתָּר, כִּי פַּעַם אַחַת לֹא מַזִּיקָה לְאַף אֶחָד","אָסוּר רַק אִם הוּא מוֹכֵר לָהֶם אֶת הַסִּיגַרְיוֹת"],1,"הָעִשּׁוּן מְסֻכָּן, וּמִי שֶׁמְּעוֹדֵד אֲחֵרִים לְעַשֵּׁן עוֹבֵר עַל ״לִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשֹׁל״. בְּיִחוּד צְעִירִים – מִי שֶׁמַּתְחִיל עָלוּל לְהִתְמַכֵּר. וּמִצְוָה לוֹמַר לוֹ בְּאַהֲבָה שֶׁיַּפְסִיק.","פֶּרֶק ט׳, הֲלָכָה י״ב","שׁוֹמְרִים עַל הַחַיִּים"],["בַּלַּיְלָה, בִּרְחוֹב רֵיק לְגַמְרֵי, הָרַמְזוֹר לְהוֹלְכֵי רֶגֶל אָדֹם. חָבֵר אוֹמֵר לְיִשַׁי: ״אֵין אַף מְכוֹנִית, בּוֹא נַעֲבֹר!״ מָה נָכוֹן?",["מֻתָּר לַעֲבֹר, כִּי הַחֹק נוֹעַד רַק לִשְׁעַת סַכָּנָה","מְחַכִּים לַיָּרֹק, כִּי הַחֹק הוּא גַּם תַּקָּנַת הַצִּבּוּר","מֻתָּר, אִם רָצִים מַהֵר וּמִסְתַּכְּלִים לִשְׁנֵי הַצְּדָדִים","מְחַכִּים, אֲבָל רַק כְּשֶׁיֵּשׁ שׁוֹטֵר שֶׁרוֹאֶה אוֹתָנוּ"],1,"הַחֻקִּים שֶׁקָּבְעוּ שְׁלִיחֵי הַצִּבּוּר מְחַיְּבִים, כָּל זְמַן שֶׁאֵינָם סוֹתְרִים אֶת הַהֲלָכָה. מִי שֶׁעוֹבֵר עֲלֵיהֶם – גַּם אִם לֹא קָרָה דָּבָר – עוֹבֵר עַל תַּקָּנַת הַקָּהָל, בְּנוֹסָף לְאִסּוּר הַהִסְתַּכְּנוּת.","פֶּרֶק י׳, הֲלָכָה ב׳","שׁוֹמְרִים עַל הַחַיִּים"]]};